/* ===== Infinity Forex Calendar ===== */
.cal{padding-top:28px;padding-bottom:20px}
.cal-head{display:flex;justify-content:space-between;align-items:flex-end;gap:16px;flex-wrap:wrap;margin-bottom:18px}
