.hi-card{position:relative;text-align:left;display:flex;flex-direction:column;gap:6px;padding:18px 20px;border-radius:20px;cursor:pointer;color:var(--text);
  border:1px solid rgba(255,92,122,.4);background:radial-gradient(420px 160px at 0% 0%,rgba(255,92,122,.22),transparent 70%),linear-gradient(135deg,rgba(124,77,255,.18),rgba(13,13,22,.9));
