.hi-name{font-family:var(--display);font-weight:500;font-size:clamp(18px,2.2vw,22px);line-height:1.25}
.hi-cd{font-size:17px;font-weight:800;font-variant-numeric:tabular-nums;background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}
.hi-card.is-live .hi-cd{background:none;color:var(--mint);font-size:15px}
.hi-time{font-size:12.5px;color:var(--muted)}
.hero-none{padding:14px 18px;border-radius:16px;border:1px solid var(--line);background:var(--panel);color:var(--muted);font-size:14px}
.cal-filters{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding:12px;border-radius:18px;background:var(--charcoal);border:1px solid var(--line);margin-bottom:18px;position:sticky;top:calc(env(safe-area-inset-top,0px) + var(--nav-h) + 6px);z-index:8}
.seg3{display:flex;background:var(--obsidian);border:1px solid var(--line-2);border-radius:12px;padding:3px}
.seg3 button{min-height:38px;padding:0 14px;border:0;border-radius:9px;background:transparent;color:var(--muted);font-weight:700;font-size:13.5px;cursor:pointer}
