.cal-sel select{height:40px;border-radius:10px;border:1px solid var(--line-2);background:var(--obsidian);padding:0 10px;font-size:14px}
.cal-tzl{display:inline-block}.cal-tzl select{height:34px;max-width:100%;border-radius:9px;border:1px solid var(--line-2);background:var(--obsidian);color:var(--text);padding:0 8px;font-size:14px;font-weight:600}
.hi-only{display:flex;align-items:center;gap:8px;min-height:40px;padding:0 12px;border-radius:10px;border:1px solid rgba(255,92,122,.35);background:rgba(255,92,122,.06);font-weight:700;font-size:13.5px;cursor:pointer}
