  border:1px solid var(--line);background:var(--panel);color:var(--text);cursor:pointer;transition:border-color .2s,background .2s;position:relative;overflow:hidden}
.ev-row:hover{border-color:rgba(155,92,255,.45);background:var(--panel-2)}
