.ev-row.imp-high::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--rose);box-shadow:0 0 12px var(--rose)}
.ev-row.st-released{opacity:.82}
.ev-row.st-live{border-color:rgba(46,230,168,.5)}
.c-time{font-weight:800;font-variant-numeric:tabular-nums;font-size:15px}
