.imp-low .c-imp .ib:nth-child(1){background:var(--muted)}
.imp-medium .c-imp .ib:nth-child(-n+2){background:var(--amber)} .imp-medium .c-imp em{color:var(--amber)}
.imp-high .c-imp .ib{background:var(--rose);box-shadow:0 0 8px rgba(255,92,122,.6)} .imp-high .c-imp em{color:#FF8FA3}
.c-v{font-variant-numeric:tabular-nums;font-size:14px;display:flex;flex-direction:column}
.c-v small{font-size:10.5px;color:var(--dim);font-weight:700}
.c-act b{font-size:15px}
.cmp{font-style:normal;font-size:10.5px;color:var(--muted);font-weight:700}
.flash{animation:calflash 1.2s ease 0s 5;border-radius:8px}
@keyframes calflash{0%,100%{background:transparent}50%{background:rgba(124,77,255,.45);box-shadow:0 0 9px rgba(124,77,255,.33)}}
.c-st{display:flex;flex-direction:column;gap:2px;align-items:flex-start}.c-st small{font-size:11px;color:var(--muted);font-variant-numeric:tabular-nums}
.pst{display:inline-flex;align-items:center;gap:5px;font-size:10.5px;font-weight:800;letter-spacing:.06em;padding:3px 8px;border-radius:999px}
.pst.upcoming{background:rgba(61,123,255,.15);color:#8FB0FF}.pst.live{background:rgba(46,230,168,.15);color:var(--mint)}.pst.released{background:rgba(255,255,255,.06);color:var(--muted)}
.ev-row.ev-focus{box-shadow:0 0 0 2px rgba(47,168,255,.75),0 0 24px rgba(139,92,246,.35);border-radius:12px}
.cal-down,.cal-empty{padding:40px 20px;text-align:center;border-radius:20px;border:1px solid var(--line);background:var(--panel)}
.cal-down{border-color:rgba(255,92,122,.35)}
.cal-down h2{font-family:var(--display);font-weight:600;font-size:clamp(16px,2.4vw,22px);margin:0 0 10px;color:#FF8FA3;letter-spacing:.02em}
.cal-down p,.cal-empty p{color:var(--muted);max-width:56ch;margin:0 auto 16px}
.cal-skel{height:58px;border-radius:14px;margin-bottom:6px;background:linear-gradient(90deg,var(--panel),var(--panel-2),var(--panel));background-size:200% 100%;animation:skel 1.4s infinite}
@keyframes skel{to{background-position:-200% 0}}
.cal-foot{font-size:12px;color:var(--dim);margin-top:22px}
.cal-drawer{position:fixed;inset:0;z-index:100}
.cal-dr-bg{position:absolute;inset:0;background:rgba(4,4,8,.6);backdrop-filter:blur(4px);-webkit-backdrop-filter:blur(4px);opacity:0;transition:opacity .2s}
.cal-dr{position:absolute;right:0;top:0;bottom:0;width:min(440px,100%);background:var(--charcoal);border-left:1px solid var(--line-2);padding:calc(env(safe-area-inset-top,0px) + 22px) 24px calc(env(safe-area-inset-bottom,0px) + 24px);overflow:auto;
  transform:translateX(30px);opacity:0;transition:transform .22s ease,opacity .22s ease;box-shadow:-30px 0 44px -18px rgba(124,77,255,.22)}
