.cal-dr h3{font-size:14px;margin:18px 0 6px}.cal-dr p{color:#C8C9DC;font-size:14.5px;line-height:1.65;margin:0}
.cal-dr .note{margin-top:18px;font-size:12px;color:var(--dim)}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.ev-row{grid-template-columns:84px 92px minmax(0,1fr) 150px 88px 88px 128px 110px}
.c-time{white-space:nowrap}

@media (max-width:1100px){ .cal-sel{margin-left:0} }
@media (max-width:900px){
  .cal-filters{position:static}
