.sig.buy{background:rgba(46,230,168,.14);color:var(--mint)}.sig.sell{background:rgba(255,92,122,.14);color:#FF8FA3}.sig.neu{background:rgba(255,255,255,.06);color:var(--muted)}
.sig.warn{background:rgba(255,194,75,.13);color:#FFD27A}.sig.cool{background:rgba(76,201,255,.12);color:#8FDCFF}.sig.na{background:transparent;color:var(--dim)}
.ix-notes{margin-top:16px;font-size:13px;color:#C8C9DC}.ix-notes p{margin:4px 0;padding:10px 14px;border-radius:12px;border:1px solid rgba(76,201,255,.2);background:rgba(10,16,48,.45)}
