@media (max-width:1100px){ .ix-core{grid-template-columns:1fr 1fr} .ix-gwrap{grid-column:1/-1;order:-1} }
@media (max-width:820px){ .ix-cats{grid-template-columns:1fr} }
@media (max-width:640px){
  .ix-ctl{width:100%}.ix-search{flex:1}.ix-search input{width:100%}.ix-tfs{width:100%;overflow-x:auto}.ix-tfs button{flex:1;min-width:40px}.ix-mtfbtn{width:100%}
  .ix-core{grid-template-columns:1fr}.ix-meta{grid-template-columns:1fr 1fr 1fr;gap:6px}.ix-meta div{padding:8px 6px}.ix-meta dd{font-size:12px}
  .ix-r{grid-template-columns:1fr auto;grid-template-areas:"n sg" "r st";gap:4px 10px;padding:9px 0}
  .ix-r.hd{display:none}.i-n{grid-area:n}.i-r{grid-area:r;font-size:12px}.ix-r>span:nth-child(3){grid-area:sg;justify-self:end}.i-s{grid-area:st;justify-self:end;min-width:70px}
  .mtf-row{grid-template-columns:40px 1fr 60px}.mtf-row .cat-split{grid-column:1/-1;order:5}
  .why-list li{grid-template-columns:1fr;gap:2px}
}
/* ===== Infinity Academy ===== */
.acad{position:relative;min-height:80vh;padding:18px 0 40px;background-image:linear-gradient(rgba(76,201,255,.045) 1px,transparent 1px),linear-gradient(90deg,rgba(76,201,255,.045) 1px,transparent 1px);background-size:40px 40px}
.acad::before{content:"";position:absolute;inset:0;pointer-events:none;background:radial-gradient(1000px 600px at 50% 0%,rgba(124,77,255,.16),transparent 60%),radial-gradient(800px 500px at 50% 60%,transparent 30%,var(--obsidian) 90%)}
