.ac-wrap{position:relative;z-index:1}
.ac-top{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:10px}
.ac-brand{display:flex;align-items:center;gap:10px;text-decoration:none}.ac-brand svg{width:40px;height:22px;filter:drop-shadow(0 0 8px rgba(155,92,255,.8))}
.ac-brand b{font-family:var(--display);letter-spacing:.24em;font-size:14px;background:linear-gradient(90deg,#CDBDFF,#4CC9FF);-webkit-background-clip:text;background-clip:text;color:transparent}
