.ac-nav{display:flex;gap:4px;overflow-x:auto;scrollbar-width:none;padding:6px;border-radius:16px;background:rgba(10,12,30,.7);border:1px solid rgba(155,92,255,.22);margin-bottom:22px;backdrop-filter:blur(10px);position:sticky;top:calc(env(safe-area-inset-top,0px) + var(--nav-h) + 6px);z-index:9}
.ac-nav::-webkit-scrollbar{display:none}
.ac-nav a{flex-shrink:0;text-decoration:none;font-size:13px;font-weight:800;letter-spacing:.04em;color:var(--muted);padding:10px 14px;border-radius:11px;transition:color .2s,background .2s}
.ac-nav a:hover{color:#fff}.ac-nav a[aria-current="page"]{color:#fff;background:linear-gradient(120deg,rgba(155,92,255,.45),rgba(61,123,255,.35));box-shadow:0 0 10px -4px rgba(155,92,255,.4),inset 0 0 0 1px rgba(205,189,255,.35)}
.ac-body{animation:pagein .35s ease}
.ac-k{font-size:11.5px;font-weight:800;letter-spacing:.2em;color:#8FDCFF;margin:0 0 6px}
.ac-h1{font-family:var(--display);font-weight:700;font-size:clamp(24px,3.4vw,36px);margin:0 0 8px}
.sm{font-size:12.5px}
.ac-card{background:linear-gradient(180deg,rgba(22,20,44,.75),rgba(10,10,24,.75));border:1px solid rgba(155,92,255,.22);border-radius:20px;padding:20px;backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);margin-bottom:16px;box-shadow:inset 0 1px 0 rgba(255,255,255,.04)}
.ac-card h3{margin:0 0 14px;font-size:12px;letter-spacing:.18em;color:#A9B9FF;font-weight:800;text-transform:uppercase}
.ac-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:46px;padding:0 20px;border-radius:12px;border:1px solid rgba(205,189,255,.45);background:linear-gradient(120deg,#8B5CF6,#3D7BFF);color:#fff;font-weight:800;font-size:14px;letter-spacing:.04em;cursor:pointer;text-decoration:none;
  clip-path:polygon(10px 0,100% 0,100% calc(100% - 10px),calc(100% - 10px) 100%,0 100%,0 10px);box-shadow:0 0 12px -4px rgba(139,92,246,.4);transition:transform .15s,filter .2s}
.ac-btn:hover{filter:brightness(1.15)}.ac-btn:active{transform:scale(.98)}.ac-btn:disabled{opacity:.45;cursor:not-allowed;filter:none}
