/* rings & bars */
.ac-ring{position:relative;width:120px;height:120px;flex-shrink:0}.ac-ring.big{width:160px;height:160px}
.ac-ring svg{width:100%;height:100%;transform:rotate(-90deg)}.rg-bg{fill:none;stroke:rgba(255,255,255,.07);stroke-width:7}
.rg-fg{fill:none;stroke:url(#none);stroke:#9B7BFF;stroke-width:7;stroke-linecap:round;transition:stroke-dashoffset 1.4s cubic-bezier(.2,.8,.2,1);filter:drop-shadow(0 0 6px rgba(155,92,255,.9))}
.ac-ring.acc .rg-fg{stroke:#4CC9FF;filter:drop-shadow(0 0 6px rgba(76,201,255,.9))}
.rg-t{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center}.rg-t b{font-family:var(--display);font-size:24px}.ac-ring.big .rg-t b{font-size:38px}.rg-t small{font-size:9.5px;letter-spacing:.16em;color:var(--muted);font-weight:800}
.ac-bar{margin-bottom:12px}.ab-h{display:flex;justify-content:space-between;font-size:13px;font-weight:700;margin-bottom:5px}.ab-h b{color:#CDBDFF}
