.ab-t.xp{height:10px;margin:10px 0 6px;max-width:420px}
/* dashboard */
.ac-hero{display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap;padding:24px;border-radius:24px;margin-bottom:16px;border:1px solid rgba(155,92,255,.35);
  background:radial-gradient(600px 240px at 0% 0%,rgba(155,92,255,.28),transparent 70%),radial-gradient(500px 240px at 100% 100%,rgba(76,201,255,.18),transparent 70%),rgba(10,10,24,.8)}
.ac-lvl{display:flex;align-items:center;gap:22px}.ac-lvl h1{font-family:var(--display);font-weight:700;font-size:clamp(24px,3.6vw,38px);margin:0}.ac-xp{font-weight:800;font-variant-numeric:tabular-nums;margin:8px 0 0}
.ac-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:16px}
