.ac-ranks li i{display:block;width:12px;height:12px;margin:0 auto 8px;border-radius:50%;border:2px solid #8B8EAA}
.ac-ranks li.on{opacity:1;border-color:rgba(155,92,255,.45)}.ac-ranks li.on i{background:#9B7BFF;border-color:#CDBDFF;box-shadow:0 0 10px #9B7BFF}
.ac-ranks b{display:block;font-size:12px}.ac-ranks small{font-size:10.5px;color:var(--dim)}
.ac-badges{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:8px}
