.ac-badge span{font-size:20px;color:var(--dim)}.ac-badge b{font-size:13px}.ac-badge small{font-size:11px;color:var(--dim)}
.ac-badge.on{opacity:1;border-style:solid;border-color:rgba(255,194,75,.5);background:rgba(255,194,75,.06)}.ac-badge.on span{color:#FFC24B;text-shadow:0 0 10px #FFC24B}
.ac-badge.unlock{animation:unlock 1s ease}@keyframes unlock{0%{transform:scale(.6);opacity:0}60%{transform:scale(1.08);opacity:1}100%{transform:none}}
