@keyframes holoscan{0%{transform:translateY(-100%)}100%{transform:translateY(260%)}}
.ac-chart{display:block;width:100%;height:auto}.ac-chart.clickable{cursor:crosshair}
.ac-grid{stroke:rgba(169,185,255,.07)}.ac-grid.v{stroke-dasharray:2 6}.ac-ax{fill:#5D6080;font:600 9.5px Manrope,system-ui}
