.pin{fill:rgba(76,201,255,.2);stroke:#4CC9FF;stroke-width:2;animation:pinpulse 1.4s ease-in-out infinite}.pin.good{stroke:#2EE6A8;fill:rgba(46,230,168,.25)}.pin.bad{stroke:#FF5C7A;fill:rgba(255,92,122,.25)}.pin-c{fill:#fff}
