/* play */
.ac-qhead{display:flex;flex-wrap:wrap;gap:8px 18px;align-items:center;padding:12px 16px;border-radius:14px;border:1px solid rgba(76,201,255,.3);background:rgba(10,16,48,.7);font-size:12px;font-weight:800;letter-spacing:.1em;color:var(--muted)}
.ac-qhead b{color:#fff;font-variant-numeric:tabular-nums;font-size:14px;margin-left:4px}.ac-mode{color:#CDBDFF;margin-right:auto}
.ac-qprog{height:3px;background:rgba(255,255,255,.06);border-radius:3px;margin:8px 0 18px;overflow:hidden}.ac-qprog i{display:block;height:100%;background:linear-gradient(90deg,#8B5CF6,#4CC9FF);box-shadow:0 0 10px #4CC9FF;transition:width .5s}
.ac-q{max-width:900px;margin:0 auto}.ac-qn{font-size:11.5px;font-weight:800;letter-spacing:.18em;color:#8FDCFF;margin:0 0 6px}
.ac-qt{font-family:var(--display);font-weight:500;font-size:clamp(18px,2.6vw,24px);margin:0 0 14px}
.ac-qchart{margin-bottom:14px}
.ac-opts{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.ac-opt{display:flex;align-items:center;gap:12px;text-align:left;min-height:56px;padding:10px 14px;border-radius:14px;border:1px solid rgba(155,92,255,.3);background:rgba(16,14,36,.8);color:var(--text);font-weight:700;font-size:14.5px;cursor:pointer;transition:border-color .2s,box-shadow .2s,transform .15s}
.ac-opt span{width:30px;height:30px;flex-shrink:0;display:grid;place-items:center;border-radius:9px;border:1px solid rgba(76,201,255,.5);color:#8FDCFF;font-weight:900}
.ac-opt:hover:not(:disabled){border-color:rgba(76,201,255,.7);box-shadow:0 0 10px -5px rgba(76,201,255,.4);transform:translateY(-1px)}
.ac-opt.right{border-color:#2EE6A8;background:rgba(46,230,168,.12);box-shadow:0 0 13px -4px rgba(46,230,168,.4)}.ac-opt.right span{background:#2EE6A8;color:#04120c;border-color:#2EE6A8}
.ac-opt.wrong{border-color:#FF5C7A;background:rgba(255,92,122,.1)}.ac-opt.wrong span{background:#FF5C7A;color:#fff;border-color:#FF5C7A}.ac-opt:disabled{cursor:default}
.ac-clickbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.ac-clickbar span{flex:1;color:var(--muted);font-weight:700;font-size:14px}
.ac-fb{margin-top:16px;padding:18px;border-radius:16px;animation:pagein .35s ease}.ac-fb p{color:#D6D7E8;line-height:1.6;margin:8px 0 12px}
.ac-fb.good{border:1px solid rgba(46,230,168,.55);background:linear-gradient(180deg,rgba(46,230,168,.12),rgba(10,10,24,.8));box-shadow:0 0 22px -10px rgba(46,230,168,.4)}
.ac-fb.bad{border:1px solid rgba(255,92,122,.5);background:linear-gradient(180deg,rgba(255,92,122,.1),rgba(10,10,24,.8))}
.fb-h{display:flex;flex-wrap:wrap;gap:12px;align-items:baseline}.fb-h b{font-family:var(--display);font-size:22px;letter-spacing:.08em}.ac-fb.good .fb-h b{color:var(--mint);text-shadow:0 0 14px rgba(46,230,168,.8)}.ac-fb.bad .fb-h b{color:#FF8FA3}.fb-h span{font-weight:700;color:#C8C9DC}
.fb-a{display:flex;gap:8px;flex-wrap:wrap}
.ac-spark{position:fixed;width:6px;height:6px;border-radius:50%;background:#2EE6A8;box-shadow:0 0 10px #2EE6A8;pointer-events:none;z-index:200;animation:spark .8s ease-out forwards}
@keyframes spark{to{transform:translate(var(--dx),var(--dy)) scale(.2);opacity:0}}
/* results */
.ac-result{text-align:center;max-width:900px;margin:0 auto}
.ac-mc{font-family:var(--display);font-weight:800;font-size:clamp(30px,6vw,56px);letter-spacing:.08em;margin:6px 0 16px;background:linear-gradient(90deg,#CDBDFF,#4CC9FF,#2EE6A8);-webkit-background-clip:text;background-clip:text;color:transparent;animation:mcin .9s cubic-bezier(.2,.9,.3,1.2)}
@keyframes mcin{from{transform:scale(.7);opacity:0;filter:blur(8px)}to{transform:none;opacity:1;filter:none}}
.ac-final small{display:block;letter-spacing:.24em;font-weight:800;color:var(--muted);font-size:12px}.ac-final b{font-family:var(--display);font-size:clamp(40px,7vw,64px);text-shadow:0 0 30px rgba(155,92,255,.8)}
.ac-rgrid{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin:20px 0}.ac-rgrid div{padding:12px 8px;border-radius:14px;background:rgba(10,16,48,.6);border:1px solid rgba(76,201,255,.22)}
.ac-rgrid small{display:block;font-size:10.5px;letter-spacing:.1em;color:var(--dim);font-weight:800}.ac-rgrid b{font-size:17px}
.ac-newb{display:flex;justify-content:center;gap:10px;flex-wrap:wrap;margin-bottom:12px}
.ac-result .ac-card{text-align:left}.ac-sw{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:10px}.ac-sw div{padding:12px;border-radius:12px;border:1px solid var(--line)}.ac-sw small{display:block;font-size:11px;color:var(--dim);font-weight:800;letter-spacing:.08em}.ac-sw a{color:#8FDCFF;font-weight:800}
.ac-ract{display:flex;flex-wrap:wrap;gap:10px;justify-content:center}
.ac-rev h3{font-size:16px;margin:4px 0 12px}.ac-rdl{display:grid;grid-template-columns:auto 1fr;gap:6px 14px;font-size:14px}.ac-rdl dt{color:var(--muted)}.ac-rdl dd{margin:0;font-weight:700}
.ac-rings{display:flex;flex-wrap:wrap;gap:18px;justify-content:center;margin:10px 0 20px}
.ac-spark-c{width:100%;height:auto}
.ac-toasts{position:fixed;right:16px;bottom:16px;z-index:150;display:flex;flex-direction:column;gap:8px}
.ac-toast{padding:12px 16px;border-radius:12px;background:#15132C;border:1px solid rgba(155,92,255,.6);box-shadow:0 0 16px -5px rgba(155,92,255,.4);font-size:13.5px;animation:unlock .6s ease}.ac-toast b{color:#CDBDFF;margin-right:6px}
.ac-toast.badge{border-color:rgba(255,194,75,.7)}.ac-toast.badge b{color:#FFC24B}.ac-toast.lvl b{color:var(--mint)}
@media (max-width:960px){ .ac-stats{grid-template-columns:repeat(2,1fr)} .ac-grid2,.ac-lesson{grid-template-columns:1fr} .ac-diffs{grid-template-columns:1fr 1fr} .ac-rgrid{grid-template-columns:repeat(3,1fr)} .ac-ranks{grid-template-columns:repeat(4,1fr)} .ac-toasts{bottom:80px;left:16px} }
@media (max-width:560px){ .ac-opts{grid-template-columns:1fr} .ac-lvl{flex-direction:column;align-items:flex-start} .ac-ring.big{width:130px;height:130px} .ac-hero{padding:18px} .ac-sw{grid-template-columns:1fr} .ac-diffs{grid-template-columns:1fr} .ac-ranks{grid-template-columns:repeat(2,1fr)} .ac-qhead{font-size:10.5px;gap:6px 12px} .ac-qhead b{font-size:13px} .ac-mode{width:100%} }

/* site nav: 12 items; About/Contact stay in the menu drawer and footer on narrower desktops */
@media (max-width:1640px) and (min-width:961px){ .nav a[data-p="/about"],.nav a[data-p="/contact"]{display:none} }
/* ===== accounts + announcement (production) ===== */
.site-ann{background:linear-gradient(90deg,rgba(139,92,246,.25),rgba(61,123,255,.2));border-bottom:1px solid rgba(155,92,255,.35);color:#E8E4FF;text-align:center;font-size:13.5px;font-weight:600;padding:8px 16px}
#acctSlot{display:flex;align-items:center;flex-shrink:0}
.acct-btn{display:inline-flex;align-items:center;gap:8px;min-height:36px;padding:0 12px;border-radius:999px;border:1px solid rgba(155,92,255,.45);background:rgba(139,92,246,.12);font-weight:700;font-size:13px;cursor:pointer;color:var(--text);white-space:nowrap}
.acct-btn span{width:22px;height:22px;border-radius:50%;display:grid;place-items:center;background:var(--grad);font-size:11px}
.acct-modal{position:fixed;inset:0;z-index:120;background:rgba(4,4,8,.7);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);display:flex;align-items:center;justify-content:center;padding:16px}
.acct-modal[hidden]{display:none}
.acct-card{position:relative;width:min(400px,100%);background:var(--charcoal);border:1px solid var(--line-2);border-radius:20px;padding:24px;display:grid;gap:12px}
.acct-card h2{font-family:var(--display);font-weight:600;font-size:22px;margin:0}.acct-sub{margin:0;color:var(--muted);font-size:13.5px}
.acct-card label{display:flex;flex-direction:column;gap:6px;font-size:13px;font-weight:700}.acct-card label small{color:var(--dim);font-weight:500}
.acct-card input{height:46px;border-radius:12px;border:1px solid var(--line-2);background:var(--obsidian);padding:0 12px;font-size:16px;color:var(--text);outline:none}
.acct-card input:focus{border-color:rgba(155,92,255,.75)}.acct-err{color:#FF8FA3;font-weight:600;font-size:13.5px;margin:0;min-height:18px}
.acct-card{max-height:calc(100dvh - 32px);overflow:auto}.acct-card.wide{width:min(460px,100%)}
.acct-pw{position:relative;display:block}.acct-pw input{width:100%;padding-right:72px}
.acct-eye{position:absolute;right:6px;top:50%;transform:translateY(-50%);height:34px;padding:0 10px;border-radius:9px;border:1px solid var(--line-2);background:var(--panel);color:var(--muted);font-size:12.5px;font-weight:700;cursor:pointer}
.acct-eye:hover{color:var(--text)}
.acct-ph{display:grid;grid-template-columns:minmax(0,132px) 1fr;gap:8px}
.acct-ph select{height:46px;border-radius:12px;border:1px solid var(--line-2);background:var(--obsidian);padding:0 8px;font-size:15px;color:var(--text);outline:none;min-width:0}
.acct-ph select:focus{border-color:rgba(155,92,255,.75)}
.acct-str{display:grid;grid-template-columns:repeat(4,1fr);gap:4px;margin-top:2px}.acct-str i{height:4px;border-radius:4px;background:var(--line-2)}
.acct-str[data-s="1"] i:nth-child(-n+1){background:var(--rose)}.acct-str[data-s="2"] i:nth-child(-n+2){background:var(--amber)}
.acct-str[data-s="3"] i:nth-child(-n+3){background:#8BD8FF}.acct-str[data-s="4"] i{background:var(--mint)}
.acct-strt{font-size:12px;font-weight:600;color:var(--dim);min-height:16px}
.acct-chk{flex-direction:row!important;align-items:flex-start;gap:10px!important;font-weight:500!important;font-size:13.5px!important;color:var(--muted);line-height:1.45}
.acct-chk input{width:18px;height:18px!important;margin:1px 0 0;flex-shrink:0;accent-color:#8B5CF6}.acct-chk a{color:#CDBDFF}
.acct-done{display:grid;gap:12px;text-align:center;padding:8px 0}.acct-done .ok-ic{width:52px;height:52px;margin:0 auto;border-radius:50%;display:grid;place-items:center;background:rgba(46,230,168,.14);color:var(--mint)}
.acct-done .ok-ic svg{width:26px;height:26px}
.acct-dev{display:grid;gap:12px;text-align:center}.acct-dev h2{margin:0;font-size:20px;line-height:1.3}.acct-devic{width:52px;height:52px;margin:0 auto;border-radius:50%;display:grid;place-items:center;background:rgba(155,92,255,.16);color:#CDBDFF}.acct-devic svg{width:24px;height:24px}
.acct-devbox{margin:0;padding:12px 14px;border-radius:12px;border:1px solid rgba(155,92,255,.3);background:rgba(155,92,255,.08);font-size:14px;line-height:1.5}
.acct-row{display:flex;gap:10px;justify-content:center;flex-wrap:wrap}.acct-row .btn{flex:1 1 140px}
.acct-otp{font:700 26px/1 ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:10px;text-align:center;padding:14px}
.acct-link{background:none;border:0;padding:0;color:#CDBDFF;font:inherit;cursor:pointer;text-decoration:underline}.acct-link:disabled{color:var(--muted);cursor:default;text-decoration:none}.acct-done p{margin:0;color:var(--muted);font-size:14px}.acct-done b{color:var(--text)}
img.acct-av{object-fit:cover;display:block}
.acct-sw{margin:0;font-size:13.5px;color:var(--muted)}.acct-x{position:absolute;right:12px;top:12px;width:36px;height:36px;border-radius:10px;border:1px solid var(--line-2);background:var(--panel);font-size:20px;cursor:pointer;color:var(--text)}
.sec-off{padding:80px 20px;text-align:center}.sec-off h1{font-family:var(--display);font-size:26px;margin:0 0 8px}
@media (max-width:960px){ .hdr .wrap{gap:10px} #acctSlot{margin-left:auto} .menu-btn{margin-right:0} .acct-btn{font-size:12px;padding:0 10px} }
.menu-btn{flex-shrink:0} #acctSlot{min-width:0}
.ac-guest{margin:0 0 14px;padding:10px 14px;border-radius:12px;border:1px solid rgba(76,201,255,.3);background:rgba(10,16,48,.55);font-size:13.5px;color:#C8C9DC}.ac-guest a{color:#8FDCFF;font-weight:700}
/* six-item bottom bar: keep labels on one line on small phones */
.bnav a{min-width:0}.bnav a span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}
@media (max-width:440px){ .bnav{padding-left:2px;padding-right:2px} .bnav a{font-size:10px;letter-spacing:-.2px} }
@media (max-width:350px){ .bnav a{font-size:9.5px;letter-spacing:-.3px} }
/* ===== Trading Journal ===== */
.jr{padding-top:24px;padding-bottom:30px}
.jr-head{display:flex;justify-content:space-between;align-items:flex-end;gap:16px;flex-wrap:wrap;margin-bottom:16px}
.jr-head h1{font-family:var(--display);font-weight:700;font-size:clamp(26px,3.6vw,38px);margin:0 0 4px}.jr-head p{margin:0}
.jr-row{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
.jr-tabs{display:flex;gap:4px;overflow-x:auto;scrollbar-width:none;padding:5px;border-radius:14px;background:var(--charcoal);border:1px solid var(--line);margin-bottom:18px}
.jr-tabs::-webkit-scrollbar{display:none}
.jr-tabs a{flex-shrink:0;text-decoration:none;padding:9px 14px;border-radius:10px;font-weight:700;font-size:13.5px;color:var(--muted)}
.jr-tabs a[aria-current="page"]{color:#fff;background:rgba(139,92,246,.2)}
.jr-gate{padding:40px 20px;text-align:center;border-radius:20px;border:1px solid var(--line);background:var(--panel)}
.jr-gate h2{font-family:var(--display);font-weight:500;font-size:22px;margin:0 0 8px}.jr-gate p{max-width:56ch;margin:0 auto 16px}.jr-gate .jr-row{justify-content:center}
.jr-loading{display:flex;align-items:center;gap:10px;padding:30px;color:var(--muted)}.jr-loading span{width:18px;height:18px;border-radius:50%;border:2px solid rgba(155,92,255,.3);border-top-color:var(--violet);animation:jrspin .8s linear infinite}
@keyframes jrspin{to{transform:rotate(360deg)}}
.jr-err{padding:14px 16px;border-radius:12px;border:1px solid rgba(255,92,122,.4);background:rgba(255,92,122,.08);color:#FFC2CD;margin-bottom:14px}
.jr-cards{display:grid;grid-template-columns:repeat(6,1fr);gap:10px;margin-bottom:16px}
.jr-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:16px}
.jr-card{padding:14px 16px;border-radius:16px;background:var(--panel);border:1px solid var(--line);display:flex;flex-direction:column;gap:2px;min-width:0}
.jr-card small{font-size:12px;font-weight:700;color:var(--muted)}.jr-card b{font-family:var(--display);font-weight:600;font-size:clamp(18px,2vw,24px);font-variant-numeric:tabular-nums;word-break:break-word}.jr-card b small{font-family:var(--body);font-size:12px;color:var(--muted)}
.jr-card span{font-size:12px;color:var(--dim)}
.jr-panel{padding:18px;border-radius:18px;background:linear-gradient(180deg,rgba(255,255,255,.035),rgba(255,255,255,.01));border:1px solid var(--line);margin-bottom:16px;min-width:0}
.jr-panel h3{margin:0 0 12px;font-size:15px}.jr-panel h3 small{font-weight:600;font-size:12px}
.jr-grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px}.jr-grid2>.jr-panel{margin-bottom:16px}
.jr-chart{width:100%;height:auto;display:block}.jr-ax{fill:var(--dim);font:600 11px var(--body)}
.jr-empty-s{margin:0;padding:16px 0}
.jr-table td,.jr-table th{white-space:nowrap}
.jr-click{cursor:pointer}.jr-click:hover td{background:rgba(255,255,255,.025)}.jr-click:focus-visible{outline:2px solid var(--cyan)}
.jr-dir{font-size:11px;font-weight:800;padding:2px 8px;border-radius:999px}.jr-dir.long{background:rgba(46,230,168,.14);color:var(--mint)}.jr-dir.short{background:rgba(255,92,122,.14);color:#FF8FA3}
.jr-res{font-size:11px;font-weight:800;padding:2px 8px;border-radius:999px;background:rgba(255,255,255,.06);color:var(--muted)}.jr-res.win{background:rgba(46,230,168,.14);color:var(--mint)}.jr-res.loss{background:rgba(255,92,122,.14);color:#FF8FA3}.jr-res.open{background:rgba(61,123,255,.15);color:#8FB0FF}
.jr-open{list-style:none;margin:0;padding:0;display:grid;gap:6px}.jr-open li{display:flex;gap:10px;align-items:center;flex-wrap:wrap;padding:10px 12px;border-radius:12px;background:rgba(255,255,255,.025);border:1px solid var(--line);font-size:14px}
.jr-form{display:grid;gap:16px}.jr-form h2{font-family:var(--display);font-weight:500;font-size:22px;margin:0}
.jr-form fieldset{border:1px solid var(--line);border-radius:18px;padding:16px 18px;margin:0;background:var(--panel)}
.jr-form legend{font-weight:800;font-size:13px;letter-spacing:.06em;color:#A9B9FF;padding:0 6px}
.jr-fields{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.jr-fields.one{grid-template-columns:1fr}
.jr-f{display:flex;flex-direction:column;gap:6px;min-width:0}.jr-f>span{font-size:13px;font-weight:700;color:#D8D8E8}.jr-f small{font-size:12px}
.jr-f input,.jr-f select,.jr-f textarea,.jr-filters input,.jr-filters select,.jr-row input{width:100%;min-height:46px;border-radius:12px;border:1px solid var(--line-2);background:var(--obsidian);padding:10px 12px;font-size:16px;color:var(--text);outline:none;font-family:inherit}
.jr-f textarea{resize:vertical;min-height:70px}.jr-f input:focus,.jr-f select:focus,.jr-f textarea:focus{border-color:rgba(155,92,255,.75);box-shadow:0 0 0 3px rgba(139,92,246,.15)}
.jr-ferr{font-style:normal;font-size:12.5px;color:#FF8FA3;font-weight:600}.jr-ferr:empty{display:none}
.jr-f.bad input,.jr-f.bad select,.jr-f.bad textarea{border-color:rgba(255,92,122,.75)}
.jr-calc{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin-bottom:14px}.jr-calc div{padding:10px 12px;border-radius:12px;background:rgba(10,16,48,.55);border:1px solid rgba(76,201,255,.2)}
.jr-calc small{display:block;font-size:11.5px;color:var(--muted);font-weight:700}.jr-calc b{font-variant-numeric:tabular-nums}
.jr-chips{display:flex;flex-wrap:wrap;gap:6px}.jr-chip{min-height:36px;padding:0 12px;border-radius:999px;border:1px solid var(--line-2);background:rgba(255,255,255,.03);color:var(--muted);font-weight:700;font-size:13px;cursor:pointer}
.jr-chip[aria-pressed="true"]{background:rgba(139,92,246,.22);border-color:rgba(155,92,255,.6);color:#fff}
.jr-shots{display:grid;grid-template-columns:1fr 1fr;gap:14px}.jr-shot{display:flex;flex-direction:column;gap:8px}.jr-shot>span{font-weight:700;font-size:13px}
.jr-shot-prev{min-height:150px;border-radius:12px;border:1px dashed var(--line-2);display:grid;place-items:center;overflow:hidden;background:var(--obsidian)}.jr-shot-prev img,.jr-shots figure img{max-width:100%;max-height:340px;display:block}
.jr-shots figure{margin:0}.jr-shots figcaption{font-weight:700;font-size:13px;margin-bottom:6px}
.jr-file{cursor:pointer}
.jr-actions{display:flex;justify-content:flex-end;gap:10px;flex-wrap:wrap}
.jr-danger{background:rgba(255,92,122,.12)!important;border:1px solid rgba(255,92,122,.5)!important;color:#FF8FA3!important}
.jr-filters{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;align-items:end;padding:14px;border-radius:16px;background:var(--charcoal);border:1px solid var(--line);margin-bottom:14px}
.jr-filters.slim{grid-template-columns:1fr 1fr 2fr}.jr-filters label{display:flex;flex-direction:column;gap:4px;font-size:12.5px;font-weight:700;color:var(--muted)}
.jr-bar{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin:12px 0}
.jr-mob{display:none}
.jr-tcard{display:grid;grid-template-columns:1fr auto;gap:4px 10px;width:100%;text-align:left;padding:14px;border-radius:14px;border:1px solid var(--line);background:var(--panel);color:var(--text);cursor:pointer;margin-bottom:8px}
.jr-back{color:var(--muted);text-decoration:none;font-weight:700;font-size:13.5px}
.jr-detail-h{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin:10px 0 14px}.jr-detail-h h2{margin:0;font-family:var(--display);font-weight:600;font-size:24px;display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.jr-dl{display:grid;grid-template-columns:1fr 1fr;gap:8px 16px;margin:0}.jr-dl div{display:flex;justify-content:space-between;gap:8px;border-bottom:1px solid var(--line);padding:6px 0;font-size:14px}.jr-dl dt{color:var(--muted)}.jr-dl dd{margin:0;font-weight:700;text-align:right;font-variant-numeric:tabular-nums}
.jr-txt h4,.jr-h4{margin:12px 0 4px;font-size:13px;color:#A9B9FF}.jr-txt p{margin:0;color:#C8C9DC;line-height:1.6;font-size:14.5px}
.jr-tags{display:flex;flex-wrap:wrap;gap:6px}.jr-tags span{font-size:12px;font-weight:700;padding:4px 10px;border-radius:999px;background:rgba(139,92,246,.18);color:#CDBDFF}.jr-tags.bad span{background:rgba(255,92,122,.12);color:#FF8FA3}
.jr-note{font-size:13.5px;color:var(--muted);margin:0 0 14px}
.jr-cal-wrap{display:grid;grid-template-columns:1.4fr 1fr;gap:16px;align-items:start}
.jr-cal{display:grid;grid-template-columns:repeat(7,1fr);gap:6px}
.jr-dow{font-size:11.5px;font-weight:800;color:var(--dim);text-align:center;padding:4px 0}
.jr-day{position:relative;min-height:78px;border-radius:12px;border:1px solid var(--line);background:rgba(255,255,255,.02);color:var(--text);display:flex;flex-direction:column;align-items:flex-start;gap:2px;padding:6px 8px;cursor:pointer;text-align:left;font-variant-numeric:tabular-nums}
.jr-day.pad{border:0;background:none;cursor:default}.jr-day .n{font-size:12px;color:var(--muted);font-weight:700}.jr-day b{font-size:12.5px}.jr-day small{font-size:11px;color:var(--dim)}
.jr-day.up{background:rgba(46,230,168,.09);border-color:rgba(46,230,168,.35)}.jr-day.up b{color:var(--mint)}.jr-day.down{background:rgba(255,92,122,.08);border-color:rgba(255,92,122,.35)}.jr-day.down b{color:#FF8FA3}
.jr-day.sel{outline:2px solid var(--violet);outline-offset:1px}.jr-day .rv{position:absolute;right:6px;top:4px;font-style:normal;font-size:12px;color:#CDBDFF}
.jr-rate{display:flex;gap:6px}.jr-rate button{width:44px;height:44px;border-radius:12px;border:1px solid var(--line-2);background:var(--obsidian);color:var(--text);font-weight:800;cursor:pointer}.jr-rate button[aria-checked="true"]{background:var(--grad);border-color:transparent}
.jr-toast{position:fixed;left:50%;transform:translateX(-50%);bottom:24px;z-index:130;padding:12px 18px;border-radius:12px;background:#15132C;border:1px solid rgba(46,230,168,.5);font-weight:600;box-shadow:0 10px 30px rgba(0,0,0,.5)}.jr-toast.bad{border-color:rgba(255,92,122,.6)}
.jr-report header h2{font-family:var(--display);margin:0}
@media (max-width:1100px){ .jr-cards{grid-template-columns:repeat(3,1fr)} .jr-fields{grid-template-columns:1fr 1fr} .jr-calc{grid-template-columns:repeat(3,1fr)} .jr-filters{grid-template-columns:repeat(2,1fr)} .jr-cal-wrap{grid-template-columns:1fr} }
@media (max-width:760px){ .jr-grid2,.jr-shots{grid-template-columns:1fr} .jr-kpis{grid-template-columns:1fr 1fr} .jr-desk{display:none} .jr-mob{display:block} .jr-dl{grid-template-columns:1fr} .jr-filters.slim{grid-template-columns:1fr 1fr} .jr-filters.slim .jr-row{grid-column:1/-1} .jr-toast{bottom:84px} }
@media (max-width:560px){ .jr-cards{grid-template-columns:1fr 1fr} .jr-fields{grid-template-columns:1fr} .jr-calc{grid-template-columns:1fr 1fr} .jr-filters{grid-template-columns:1fr 1fr} .jr-day{min-height:58px;padding:4px} .jr-day b{font-size:10.5px} .jr-day small{display:none} .jr-head .jr-row{width:100%} .jr-head .jr-row .btn{flex:1} }
@media print{ .hdr,.bnav,footer,.site-ann,.noprint,.jr-head .jr-row,.jr-tabs{display:none!important} body,.jr-panel,.jr-card{background:#fff!important;color:#000!important;border-color:#ccc!important} body::before{display:none} .jr-card b,.jr-panel h3,td,th{color:#000!important} .jr-report .tbl-wrap{overflow:visible;max-height:none} }
.jr-filters label,.jr-filters input,.jr-filters select{min-width:0}
.jr-bar .btn{white-space:nowrap}
@media (max-width:560px){ .jr-bar{justify-content:flex-start} .jr-bar>.btn{flex:1 1 auto} .jr-filters input[type=date]{font-size:14px;padding:8px} }

.jr-calbar{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:10px;margin-bottom:12px}.jr-calbar h3{margin:0;text-align:center}
.jr-cal{grid-template-columns:repeat(7,minmax(0,1fr))}
@media (max-width:560px){ .jr-head .btn{font-size:13.5px;padding:0 12px;white-space:nowrap} .jr-calbar .btn{padding:0 14px} }
/* ===== Strategies ===== */
.strat{padding:18px 0 40px;background-image:linear-gradient(rgba(124,77,255,.04) 1px,transparent 1px),linear-gradient(90deg,rgba(124,77,255,.04) 1px,transparent 1px);background-size:42px 42px}
.s-prev{margin:0 0 12px;padding:10px 14px;border-radius:12px;border:1px solid rgba(255,194,75,.35);background:rgba(255,194,75,.06);color:#E6DCC0;font-size:13.5px}
.s-kicker{font-family:var(--display);font-weight:800;letter-spacing:.24em;font-size:13px;margin:0 0 10px;background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}
.s-nav,.s-tabs{display:flex;gap:4px;overflow-x:auto;scrollbar-width:none;padding:5px;border-radius:14px;background:rgba(10,12,30,.7);border:1px solid rgba(155,92,255,.22);margin-bottom:18px}
.s-nav::-webkit-scrollbar,.s-tabs::-webkit-scrollbar{display:none}
.s-nav a,.s-tabs a{flex-shrink:0;text-decoration:none;padding:9px 13px;border-radius:10px;font-weight:700;font-size:13.5px;color:var(--muted)}
.s-nav a[aria-current="page"],.s-tabs a[aria-current="page"]{color:#fff;background:linear-gradient(120deg,rgba(155,92,255,.45),rgba(61,123,255,.3))}
.s-title{font-family:var(--display);font-weight:700;font-size:clamp(24px,3.4vw,36px);margin:0 0 6px}.s-sub{margin:0 0 14px}
.s-note{font-size:13.5px;color:var(--muted);padding:10px 14px;border-radius:12px;border:1px solid rgba(76,201,255,.25);background:rgba(10,16,48,.45)}.s-note a{color:#8FDCFF;font-weight:700}
.s-search{display:flex;gap:8px;margin:12px 0}.s-search input{flex:1;min-width:0;height:50px;border-radius:14px;border:1px solid rgba(76,201,255,.35);background:rgba(10,16,48,.6);padding:0 16px;font-size:16px;color:var(--text);outline:none}
.s-res ul,.s-list{list-style:none;margin:0;padding:0;display:grid;gap:6px}.s-res a,.s-list a{display:flex;align-items:center;gap:10px;padding:11px 12px;border-radius:12px;background:rgba(255,255,255,.025);border:1px solid var(--line);text-decoration:none;flex-wrap:wrap}
.s-list a:hover,.s-res a:hover{border-color:rgba(155,92,255,.5)}.s-list a small{margin-left:auto}
.s-check{width:22px;height:22px;border-radius:50%;border:1.5px solid var(--line-2);display:grid;place-items:center;font-size:12px;flex-shrink:0}.s-list a.done .s-check{background:var(--mint);border-color:var(--mint);color:#04120c;font-weight:900}
.s-pill{font-size:10.5px;font-weight:800;letter-spacing:.06em;padding:3px 8px;border-radius:999px}.s-pill.smc{background:rgba(139,92,246,.22);color:#CDBDFF}.s-pill.pa{background:rgba(76,201,255,.16);color:#8FDCFF}.s-pill.ict{background:rgba(46,230,168,.14);color:var(--mint)}
.s-continue{display:flex;flex-direction:column;gap:2px;padding:16px 18px;border-radius:16px;text-decoration:none;margin:12px 0;border:1px solid rgba(155,92,255,.45);background:linear-gradient(120deg,rgba(139,92,246,.2),rgba(61,123,255,.12));box-shadow:0 0 13px -7px rgba(155,92,255,.4)}
.s-continue small{color:#8FDCFF;font-weight:800;letter-spacing:.1em;font-size:11px;text-transform:uppercase}.s-continue b{font-size:17px}.s-continue span{color:var(--muted);font-size:13px}
.s-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:14px 0}
.s-card{position:relative;padding:22px;border-radius:22px;border:1px solid rgba(155,92,255,.3);background:radial-gradient(400px 200px at 100% 0%,rgba(124,77,255,.2),transparent 70%),linear-gradient(180deg,rgba(20,20,40,.85),rgba(10,10,22,.85));display:flex;flex-direction:column;gap:14px;transition:transform .2s,box-shadow .2s}
.s-card:hover{transform:translateY(-2px);box-shadow:0 18px 22px -12px rgba(124,77,255,.4)}.s-card.s-pa{background:radial-gradient(400px 200px at 100% 0%,rgba(76,201,255,.16),transparent 70%),linear-gradient(180deg,rgba(20,20,40,.85),rgba(10,10,22,.85))}.s-card.s-ict{background:radial-gradient(400px 200px at 100% 0%,rgba(46,230,168,.14),transparent 70%),linear-gradient(180deg,rgba(20,20,40,.85),rgba(10,10,22,.85))}
.s-card-top{display:flex;justify-content:space-between;gap:10px}.s-card h2{font-family:var(--display);font-weight:800;font-size:26px;margin:0;letter-spacing:.04em}.s-card p{margin:2px 0;font-weight:700}.s-card small{color:var(--muted);font-size:12.5px}
.s-stats{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:0}.s-stats.wide{grid-template-columns:repeat(3,1fr)}.s-stats div{padding:10px 12px;border-radius:12px;background:rgba(0,0,0,.25);border:1px solid var(--line);min-width:0}
.s-stats dt{font-size:11px;font-weight:800;color:var(--dim);letter-spacing:.04em}.s-stats dd{margin:2px 0 0;font-weight:800;font-size:14.5px;word-break:break-word}.s-stats dd a{color:#CDBDFF}
.s-lvl{display:inline-block;font-size:11px;font-weight:800;letter-spacing:.06em;padding:3px 9px;border-radius:999px;background:rgba(139,92,246,.2);color:#CDBDFF}
.s-btns{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.s-btns .btn{min-height:46px;padding:0 8px;font-size:13.5px}
.s-cont{font-size:13px;color:#8FDCFF;text-decoration:none}
.s-ring{position:relative;flex-shrink:0}.s-ring svg{width:100%;height:100%;transform:rotate(-90deg)}.sr-bg{fill:none;stroke:rgba(255,255,255,.08);stroke-width:8}.sr-fg{fill:none;stroke:#9B7BFF;stroke-width:8;stroke-linecap:round;transition:stroke-dashoffset 1.2s ease;filter:drop-shadow(0 0 5px rgba(155,92,255,.8))}
.s-ring>div{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}.s-ring b{font-family:var(--display);font-size:20px}.s-ring small{font-size:10px;color:var(--muted);font-weight:800;letter-spacing:.06em;text-transform:uppercase;max-width:80%}
.s-overall{display:flex;gap:20px;align-items:center}.s-overall .s-stats{flex:1}
.s-quick{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.s-quick a{text-decoration:none;display:flex;flex-direction:column;gap:4px;min-width:0;overflow-wrap:anywhere}.s-quick a:hover{border-color:rgba(155,92,255,.5)}
.s-disc{font-size:12px;color:var(--dim);margin-top:20px}
.s-chead{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:14px}.s-chead h1{font-family:var(--display);font-weight:700;font-size:clamp(22px,3vw,32px);margin:0}
.s-mod{margin-bottom:20px}.s-mod h2{font-size:15px;letter-spacing:.08em;color:#A9B9FF;margin:0 0 10px}
.s-lib{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px}.s-mat{padding:16px;border-radius:16px;background:var(--panel);border:1px solid var(--line);display:flex;flex-direction:column;gap:8px}.s-mat h3{margin:0;font-size:15.5px}.s-mat p{margin:0;font-size:13.5px}
.s-mat-h{display:flex;gap:8px;align-items:center;flex-wrap:wrap;font-size:12px}.s-type{font-weight:800;color:var(--muted)}.s-mat .btn{align-self:flex-start;min-height:38px}.s-body{font-size:14px;color:#C8C9DC;line-height:1.6;padding-top:6px}
.s-filters{display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin:12px 0}.s-sep{width:1px;height:24px;background:var(--line-2);margin:0 4px}.s-filters select{height:40px;border-radius:10px;border:1px solid var(--line-2);background:var(--obsidian);padding:0 10px;color:var(--text)}
.s-quizzes{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.s-quizzes h3{margin:0 0 6px}.s-quizzes .btn{margin-top:10px}
/* lesson */
.s-lesson{max-width:900px;margin:0 auto}.s-crumb{font-size:13px;color:var(--muted)}.s-crumb a{color:#CDBDFF;text-decoration:none}
.s-lh h1{font-family:var(--display);font-weight:700;font-size:clamp(24px,3.6vw,38px);margin:10px 0 8px;line-height:1.15}.s-meta{display:flex;gap:12px;flex-wrap:wrap;align-items:center;font-size:13.5px;color:var(--muted)}
.s-acts{margin:12px 0}.s-acts .btn{min-height:42px;font-size:13.5px}.s-acts [aria-pressed="true"]{border-color:rgba(255,194,75,.6);color:#FFD27A}
.s-obj{padding:16px 18px;border-radius:16px;border:1px solid rgba(76,201,255,.3);background:rgba(10,16,48,.55);margin:14px 0}.s-obj h2,.s-sec h2,.s-h2{font-size:13px;letter-spacing:.14em;text-transform:uppercase;color:#8FDCFF;margin:0 0 8px}.s-obj p{margin:0;font-size:16px}
.s-sec{margin:22px 0}.s-sec p{color:#D0D1E2;line-height:1.75;font-size:16px}.s-sec h3{font-size:15px;margin:14px 0 4px}
.s-fig{position:relative;margin:10px 0;border-radius:16px;border:1px solid rgba(76,201,255,.3);background:rgba(6,8,22,.85);padding:6px;overflow:hidden}
.s-edu{position:absolute;left:10px;top:8px;z-index:2;font-size:10.5px;font-weight:800;letter-spacing:.08em;padding:3px 8px;border-radius:6px;background:rgba(255,194,75,.15);color:#FFD27A}
.s-ex2{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:18px 0}.s-ex{padding:16px;border-radius:16px;border:1px solid var(--line);background:var(--panel)}.s-ex h3{margin:0 0 6px;font-size:15px}.s-ex p{margin:6px 0 0;color:#C8C9DC;line-height:1.6;font-size:14.5px}
.s-ex.bull{border-color:rgba(46,230,168,.35)}.s-ex.bull h3{color:var(--mint)}.s-ex.bear{border-color:rgba(255,92,122,.35)}.s-ex.bear h3{color:#FF8FA3}.s-ex.s-good{border-color:rgba(46,230,168,.35)}.s-ex.s-good h3{color:var(--mint)}.s-ex.s-bad{border-color:rgba(255,92,122,.35)}.s-ex.s-bad h3{color:#FF8FA3}
.s-ul{margin:0;padding-left:20px;line-height:1.7;color:#D0D1E2}.s-ul.bad li::marker{color:#FF8FA3}
.s-imgs{display:grid;gap:12px}.s-imgs figure{position:relative;margin:0}.s-imgs img{max-width:100%;border-radius:12px;display:block}.s-imgs figcaption{font-size:13px;color:var(--muted);margin-top:4px}
.s-exercise{padding:18px;border-radius:16px;border:1px dashed rgba(155,92,255,.45);background:rgba(139,92,246,.06)}
.s-q{padding:14px;border-radius:14px;background:rgba(255,255,255,.02);border:1px solid var(--line);margin-bottom:12px}.s-qp{font-weight:700;font-size:16px;margin:0 0 10px}
.s-opts{display:grid;gap:8px}.s-opt{display:flex;gap:10px;align-items:center;text-align:left;min-height:52px;padding:10px 14px;border-radius:12px;border:1px solid rgba(155,92,255,.3);background:rgba(16,14,36,.8);color:var(--text);font-weight:700;font-size:15px;cursor:pointer}
.s-opt b{width:28px;height:28px;display:grid;place-items:center;border-radius:8px;border:1px solid rgba(76,201,255,.5);color:#8FDCFF;flex-shrink:0}
.s-opt:hover:not(:disabled){border-color:rgba(76,201,255,.7)}.s-opt.right{border-color:#2EE6A8;background:rgba(46,230,168,.12)}.s-opt.wrong{border-color:#FF5C7A;background:rgba(255,92,122,.1)}.s-opt:disabled{cursor:default}
.s-fb{margin-top:10px;padding:12px 14px;border-radius:12px}.s-fb p{margin:4px 0 0;color:#D0D1E2;font-size:14.5px;line-height:1.6}.s-fb a{color:#8FDCFF;font-weight:700}
.s-fb.good{border:1px solid rgba(46,230,168,.5);background:rgba(46,230,168,.08)}.s-fb.good b{color:var(--mint)}.s-fb.bad{border:1px solid rgba(255,92,122,.5);background:rgba(255,92,122,.07)}.s-fb.bad b{color:#FF8FA3}
.s-complete{display:flex;justify-content:center;margin:24px 0}.s-complete .btn{min-height:54px;padding:0 30px;font-size:16px}
.s-pager{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap}.s-pager a{flex:1;min-width:200px;padding:14px;border-radius:14px;border:1px solid var(--line);background:var(--panel);text-decoration:none}.s-pager a small{display:block;color:var(--dim)}.s-pager a:last-child{text-align:right}
.s-tz{display:flex;gap:8px;align-items:center;font-size:13.5px;font-weight:700;margin-bottom:8px}.s-tz select{height:40px;border-radius:10px;border:1px solid var(--line-2);background:var(--obsidian);color:var(--text);padding:0 8px}
.s-qhead{display:flex;gap:16px;flex-wrap:wrap;align-items:center;padding:12px 16px;border-radius:14px;border:1px solid rgba(76,201,255,.3);background:rgba(10,16,48,.7);font-size:13px;color:var(--muted)}.s-qhead b{color:#fff;margin-right:auto}
.s-qbar{height:3px;background:rgba(255,255,255,.06);border-radius:3px;margin:8px 0 16px;overflow:hidden}.s-qbar i{display:block;height:100%;background:var(--grad)}
.s-result{text-align:center;display:flex;flex-direction:column;align-items:center;gap:12px;margin-bottom:18px}.s-result h1{font-family:var(--display);font-size:clamp(28px,5vw,46px);margin:0;background:linear-gradient(90deg,#CDBDFF,#4CC9FF,#2EE6A8);-webkit-background-clip:text;background-clip:text;color:transparent}.s-result .s-stats{width:100%;max-width:640px}
.s-rev{padding:12px 14px;border-radius:12px;border:1px solid var(--line);margin-bottom:8px;font-size:14px}.s-rev.good{border-color:rgba(46,230,168,.35)}.s-rev.bad{border-color:rgba(255,92,122,.35)}.s-rev p{margin:4px 0 0}
.s-rings{display:flex;flex-wrap:wrap;gap:18px;justify-content:center;margin:12px 0 18px}.s-rings a{text-decoration:none;display:flex;flex-direction:column;align-items:center;gap:6px}
.s-badges{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:10px}.s-badge{padding:14px;border-radius:14px;border:1px dashed var(--line-2);opacity:.55;display:flex;flex-direction:column;gap:3px}.s-badge span{font-size:22px;color:var(--dim)}.s-badge small{color:var(--dim)}.s-badge em{font-style:normal;font-size:11px;font-weight:800;color:#FFC24B}
.s-badge.on{opacity:1;border-style:solid;border-color:rgba(255,194,75,.5);background:rgba(255,194,75,.06)}.s-badge.on span{color:#FFC24B;text-shadow:0 0 10px #FFC24B}
.s-cert{max-width:760px;margin:20px auto;padding:40px;text-align:center;border-radius:20px;border:2px solid rgba(155,92,255,.5);background:radial-gradient(500px 240px at 50% 0%,rgba(124,77,255,.2),transparent 70%),var(--charcoal)}.s-cert svg{width:70px;height:40px}.s-cert h1{font-family:var(--display);margin:6px 0}.s-cert h2{font-family:var(--display);font-size:28px;margin:6px 0;color:#CDBDFF}
.s-acad .s-acad-g{display:grid;grid-template-columns:1fr 1.4fr;gap:12px;align-items:start}
.s-bnav{display:none}
body.s-full .hdr,body.s-full footer,body.s-full .bnav,body.s-full .s-bnav,body.s-full .s-head,body.s-full .site-ann{display:none!important}body.s-full .strat{padding-top:10px}
@media (max-width:1000px){ .s-cards{grid-template-columns:1fr} .s-quick{grid-template-columns:repeat(2,minmax(0,1fr))} }
@media (max-width:960px){ body.strat-mode .bnav{display:none} .s-bnav{display:flex;position:fixed;left:0;right:0;bottom:0;z-index:55;background:rgba(12,12,20,.94);backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px);border-top:1px solid var(--line);padding:6px 6px env(safe-area-inset-bottom,0px)}
