/* ===== Daily Mission Brief (plain panel, same look as the rest of the site) ===== */
.brief{position:fixed;right:20px;bottom:20px;z-index:110;width:min(370px,calc(100vw - 24px));max-height:calc(100vh - 40px);overflow:auto;padding:18px;border-radius:16px;
  border:1px solid var(--line-2);background:var(--charcoal);box-shadow:0 20px 50px -18px rgba(0,0,0,.85);font-family:var(--body);color:var(--text);animation:brIn .25s ease}
.brief.out{animation:brOut .2s ease forwards}
@keyframes brIn{from{opacity:0;transform:translateY(10px)}}@keyframes brOut{to{opacity:0;transform:translateY(8px)}}
.br-h{display:flex;align-items:center;gap:10px;margin-bottom:14px}.br-h b{font-family:var(--display);font-size:16px;font-weight:700}
