.br-form{display:grid;gap:12px}.br-f{display:grid;gap:6px}.br-f>span{font-size:13px;font-weight:600;color:var(--muted)}
.br-risk{position:relative}.br-risk input,.br-f select,.br-ev input{width:100%;height:42px;border-radius:10px;border:1px solid var(--line-2);background:var(--obsidian);color:var(--text);padding:0 12px;font:600 15px var(--body);outline:none}
.br-risk input.bad{border-color:#FF5C7A}.br-risk i{position:absolute;right:12px;top:50%;transform:translateY(-50%);font-style:normal;color:var(--dim);font-weight:700}
.br-f select:focus,.br-risk input:focus,.br-ev input:focus{border-color:rgba(139,92,246,.7);box-shadow:0 0 0 3px rgba(139,92,246,.15)}
.br-seg{display:grid;grid-template-columns:1fr 1fr;gap:6px}.br-seg button{height:40px;border-radius:10px;border:1px solid var(--line-2);background:var(--obsidian);color:var(--muted);font:700 13.5px var(--body);cursor:pointer}
.br-seg button[aria-pressed="true"]{color:#fff;border-color:transparent;background:var(--grad)}
.br-ev{display:grid;grid-template-columns:1fr auto;gap:6px;align-items:center}.br-ev output{font-size:13px;color:var(--muted);min-height:20px;grid-column:1/-1}.br-ev select{width:auto;height:38px;font-size:13px}.br-ev input{height:38px}
.br-ev select{grid-column:1}.br-ev input{grid-column:2;width:90px}
.br-act{display:flex;gap:8px;justify-content:flex-end;margin-top:4px}
