.br-skip{border:1px solid var(--line-2);background:none;color:var(--muted)}.br-skip:hover{color:var(--text)}
.br-go{border:0;background:var(--grad);color:#fff}
.br-status{display:flex;align-items:center;gap:12px;padding:14px;border-radius:12px;border:1px solid}
.br-status small{display:block;font-size:12px;font-weight:600;opacity:.85}.br-status b{font-family:var(--display);font-size:18px}
.br-light{width:14px;height:14px;border-radius:50%;flex-shrink:0}
