.br-status.amber{border-color:rgba(255,194,75,.5);background:rgba(255,194,75,.07);color:#FFD27A}.br-status.amber .br-light{background:#FFC24B}
.br-status.red{border-color:rgba(255,92,122,.55);background:rgba(255,92,122,.08);color:#FF8FA3}.br-status.red .br-light{background:#FF5C7A}
