@media (max-width:960px){ .brief{right:12px;left:12px;width:auto;bottom:calc(var(--bnav-h,64px) + 12px);max-height:calc(100vh - var(--bnav-h,64px) - 90px)} body.strat-mode .brief{bottom:76px} }
@media (prefers-reduced-motion:reduce){ .brief{animation:none!important} }
