.hm-top{display:grid;grid-template-columns:1.4fr 1fr;gap:14px;margin-bottom:14px}.hm-top .jr-panel{margin:0}
.hm-sh{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:10px}.hm-sh h2{font-size:15px;margin:0}.hm-tfb{font-size:11px;font-weight:800;padding:3px 8px;border-radius:999px;background:rgba(139,92,246,.18);color:#CDBDFF}
.hm-csl{list-style:none;margin:0;padding:0;display:grid;gap:6px}.hm-csl li{display:grid;grid-template-columns:22px 44px 1fr 48px;gap:8px;align-items:center;font-size:14px}.hm-csl.dim li{grid-template-columns:44px 1fr 48px;opacity:.45}
