.hm-csbar i{position:absolute;top:0;bottom:0;border-radius:999px}.hm-csbar i.pos{background:linear-gradient(90deg,rgba(46,230,168,.5),#2EE6A8)}.hm-csbar i.neg{background:linear-gradient(270deg,rgba(255,92,122,.5),#FF5C7A)}
.hm-small{font-size:12px;margin:10px 0 0}.hm-nd{margin:0 0 8px;font-weight:800;letter-spacing:.1em;color:#C8C9DC;font-size:13px}
.hm-gold{border-color:rgba(255,194,75,.35)}.hm-goldt{font-size:11px;font-weight:800;letter-spacing:.12em;padding:3px 8px;border-radius:6px;background:rgba(255,194,75,.14);color:#FFD27A;vertical-align:middle;margin-left:6px}
.hm-bar{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin-bottom:10px}.hm-cats{display:flex;gap:6px;flex-wrap:wrap}
