.hm-lg.sb i{background:#11B37E}.hm-lg.b i{background:rgba(46,230,168,.45)}.hm-lg.n i{background:#2A2B3A}.hm-lg.s i{background:rgba(255,92,122,.45)}.hm-lg.ss i{background:#D93A5A}.hm-lg.nd i{background:repeating-linear-gradient(45deg,#1b1b28 0 3px,#24243a 3px 6px)}
.hm-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(176px,1fr));gap:10px}
