.hm-cell.s{background:linear-gradient(160deg,rgba(255,92,122,calc(var(--hm-a)*.45)),rgba(44,18,26,.95));border-color:rgba(255,92,122,.35)}
.hm-cell.ss{background:linear-gradient(160deg,rgba(217,58,90,var(--hm-a)),rgba(110,20,40,.9));border-color:rgba(255,92,122,.6)}
.hm-cell.sb .hm-st,.hm-cell.b .hm-st{color:#BFFFE9}.hm-cell.ss .hm-st,.hm-cell.s .hm-st{color:#FFD1DA}.hm-cell.n .hm-st{color:#C8C9DC}
.hm-cell.nd{background:repeating-linear-gradient(45deg,#15151f 0 8px,#191926 8px 16px);border-style:dashed}.hm-ndt{margin:4px 0;font-weight:800;letter-spacing:.1em;font-size:12px;color:#9C9EB8}
