html:root:root .acct-wrap .acct-btn .acct-nm{color:#FFFFFF}
html:root:root .acct-wrap .acct-btn .nv-chev{color:#D6D6D6}
html:root:root .acct-menu{background:#1E1E1E;border:1px solid rgba(205,205,210,.22);box-shadow:0 24px 60px -18px rgba(0,0,0,.7)}
