.ah-na-key{display:inline-flex;align-items:center;gap:6px;margin-left:8px}.ah-na-key i{width:16px;height:10px;border-radius:3px;background:repeating-linear-gradient(45deg,#1b1b28 0 3px,#24243a 3px 6px);border:1px dashed var(--line-2)}
.ah-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:10px}
.ah-grid.ah-cur{grid-template-columns:repeat(auto-fill,minmax(130px,1fr));margin-bottom:18px}
.ah-cell{--ah-bg:rgba(60,62,90,.5);position:relative;text-align:left;font:inherit;color:var(--text);padding:12px;border-radius:14px;border:1px solid rgba(255,255,255,.1);cursor:pointer;min-width:0;display:flex;flex-direction:column;gap:3px;
  background:linear-gradient(160deg,var(--ah-bg),rgba(13,13,24,.92) 140%);transition:transform .15s,box-shadow .15s}
