.ah-cell.na{background:repeating-linear-gradient(45deg,#15151f 0 8px,#191926 8px 16px);border-style:dashed;color:#9C9EB8}
.ah-ct{display:flex;align-items:center;gap:6px;flex-wrap:wrap}.ah-ct b{font-size:14.5px}
.ah-px{font-size:9.5px;font-weight:800;padding:2px 6px;border-radius:5px;background:rgba(255,194,75,.2);color:#FFD27A}
.ah-cv{font-family:var(--display);font-size:20px;font-variant-numeric:tabular-nums}
.ah-cl{font-size:11.5px;font-weight:900;letter-spacing:.07em}.ah-cs{font-size:11px;color:rgba(255,255,255,.7);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ah-cell.na .ah-cl{color:#9C9EB8}.ah-cell.na .ah-cs{color:var(--dim);white-space:normal}
.ah-skel{min-height:96px;cursor:default;background:linear-gradient(100deg,#15151f 30%,#1d1d2c 50%,#15151f 70%);background-size:300% 100%;animation:ahSk 1.4s infinite}
