.ah-unavail{padding:14px 16px;border-radius:14px;border:1px dashed rgba(255,255,255,.18);background:rgba(255,255,255,.025);margin-bottom:12px}.ah-unavail b{letter-spacing:.12em;font-size:13px;color:#C8C9DC}.ah-unavail p{margin:6px 0 0;color:var(--muted);font-size:13.5px}
.ah-empty{padding:28px 18px;border-radius:16px;border:1px dashed var(--line-2);text-align:center}.ah-empty p{margin:0 0 10px}
.ah-h2{font-size:15px;margin:6px 0 10px}
.ah-mx-wrap{overflow-x:auto;border-radius:14px;border:1px solid var(--line);background:var(--panel)}
.ah-mx{border-collapse:separate;border-spacing:3px;min-width:100%;font-variant-numeric:tabular-nums}
.ah-mx th{font-size:11.5px;font-weight:800;color:var(--muted);padding:6px 8px;white-space:nowrap;text-align:center}.ah-mx tbody th{text-align:left;color:var(--text);position:sticky;left:0;background:var(--panel);z-index:1}
.ah-mx td{min-width:58px;height:40px;text-align:center;font-size:12.5px;font-weight:800;border-radius:8px;background:rgba(60,62,90,.4)}
.ah-mx td.na{background:repeating-linear-gradient(45deg,#15151f 0 5px,#1b1b29 5px 10px);color:var(--dim);font-weight:700}.ah-mx td.self{background:rgba(255,255,255,.04);color:var(--dim)}
.ah-mx.sess td{min-width:96px;line-height:1.15}.ah-mx.sess td small{display:block;font-size:10px;font-weight:700;color:rgba(255,255,255,.7)}
.ah-mx tr.focus th{color:#CDBDFF}
.ah-live{font-style:normal;font-size:9px;padding:1px 5px;border-radius:4px;background:rgba(46,230,168,.18);color:var(--mint);margin-left:4px}
.ah-act{font-size:13px;color:var(--muted);margin:0 0 10px}
/* Infinity Vision table */
.ah-vlegend{display:flex;flex-wrap:wrap;gap:6px 14px;font-size:12px;color:var(--muted);margin-bottom:10px}.ah-vlegend b{color:var(--text)}
.ah-vk{display:inline-flex;align-items:center;gap:5px}
.ah-pills i,.ah-vk i,.ah-fpil i{display:inline-block;width:10px;height:10px;border-radius:50%}
.pv-live{background:#2EE6A8;box-shadow:0 0 8px rgba(46,230,168,.6)}.pv-proxy{background:#FFC24B}.pv-missing{background:transparent;border:1.5px dashed #6B6D87}
.ah-vtable{display:grid;gap:6px}
.ah-vrow{display:grid;grid-template-columns:minmax(110px,1.1fr) 48px 104px minmax(120px,1.2fr) minmax(120px,1.2fr) 92px minmax(130px,1.3fr) 108px;gap:10px;align-items:center;padding:10px 12px;border-radius:12px;border:1px solid var(--line);background:linear-gradient(90deg,rgba(139,92,246,.06),rgba(61,123,255,.03));cursor:pointer;font-size:13.5px}
.ah-vrow:hover{border-color:rgba(155,92,255,.4)}.ah-vrow.focus{box-shadow:0 0 0 2px #9B7BFF}
.ah-vhead{background:none;border-color:transparent;cursor:default;font-size:10.5px;font-weight:800;letter-spacing:.08em;color:var(--dim);text-transform:uppercase;padding-top:0;padding-bottom:0}
.ah-vasset{display:flex;gap:6px;align-items:center;flex-wrap:wrap}.ah-vtf{color:var(--muted);font-weight:800;font-size:12px}
.ah-bias{display:inline-block;padding:4px 10px;border-radius:999px;font-weight:900;font-size:12px;letter-spacing:.05em}
.b-bull{background:rgba(46,230,168,.16);color:#7DF5CB;box-shadow:inset 0 0 0 1px rgba(46,230,168,.45)}.b-bear{background:rgba(255,92,122,.15);color:#FF9DB0;box-shadow:inset 0 0 0 1px rgba(255,92,122,.45)}
.b-neu{background:rgba(255,255,255,.06);color:#C8C9DC}.b-na{background:none;color:var(--dim);box-shadow:inset 0 0 0 1px var(--line-2)}
.ah-vnum{display:flex;align-items:center;gap:8px}.ah-vnum em{font-style:normal;font-weight:800;min-width:24px;text-align:right;font-variant-numeric:tabular-nums}
.ah-bar{flex:1;height:8px;border-radius:999px;background:rgba(255,255,255,.06);overflow:hidden}.ah-bar i{display:block;height:100%;border-radius:999px}
.s-bull i{background:linear-gradient(90deg,#1aa57a,#2EE6A8)}.s-bear i{background:linear-gradient(90deg,#b8324f,#FF5C7A)}.s-neu i{background:#6B6D87}.s-conf i{background:var(--grad)}
.ah-dash{color:var(--dim)}
.ah-risk{font-weight:800;font-size:12.5px}.r-low{color:var(--mint)}.r-medium{color:#FFD27A}.r-high{color:#FF8FA3}.r-unknown{color:var(--dim)}
.ah-cond{color:var(--text);font-weight:600}
.ah-pills{display:flex;align-items:center;gap:4px}.ah-pills small{margin-left:4px;color:var(--dim);font-weight:800;font-size:11px}
/* focus panel */
.ah-focus{position:relative;margin-top:14px;padding:16px 18px;border-radius:16px;border:1px solid rgba(155,92,255,.35);background:linear-gradient(160deg,rgba(139,92,246,.12),rgba(61,123,255,.06))}
.ah-focus h3{margin:0 0 10px;font-size:16px}.ah-focus h3 small{font-size:11px;color:#CDBDFF;margin-left:6px;letter-spacing:.06em}
.ah-fdl{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:8px;margin:0}.ah-fdl div{padding:8px 10px;border-radius:10px;background:rgba(0,0,0,.25)}
.ah-fdl dt{font-size:10px;font-weight:800;letter-spacing:.08em;color:var(--dim);text-transform:uppercase}.ah-fdl dd{margin:3px 0 0;font-weight:800;font-size:13.5px}
.ah-fpil{list-style:none;padding:0;margin:12px 0 0;display:grid;gap:6px;font-size:13px;color:var(--muted)}.ah-fpil i{margin-right:8px;vertical-align:-1px}
.ah-x{position:absolute;top:8px;right:10px;width:34px;height:34px;border-radius:10px;border:0;background:rgba(255,255,255,.06);color:var(--text);font-size:20px;cursor:pointer}
@media (max-width:1100px){
  .ah-vrow{grid-template-columns:1fr 1fr;gap:6px 12px}.ah-vhead{display:none}
  .ah-vrow .ah-vtf{text-align:right}.ah-vnum::before{content:attr(data-l);font-size:10px;font-weight:800;letter-spacing:.06em;color:var(--dim);text-transform:uppercase;min-width:74px}
  .ah-vnum{grid-column:1/-1}
}
@media (max-width:560px){
  .ah-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.ah-cell{padding:10px}.ah-cv{font-size:17px}
