  .ah-assets .hm-cats{flex-wrap:nowrap;overflow-x:auto;width:100%;scrollbar-width:none}.ah-assets input{max-width:none}.ah-assets select{flex:1 1 140px}
  .ah-info{flex-direction:column}.ah-legend>i{width:120px}
}
.ah-cpick{width:100%}.ah-cpick summary{cursor:pointer;font-size:13px;font-weight:800;color:var(--text);padding:10px 12px;border-radius:12px;border:1px solid var(--line-2);background:var(--obsidian);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ah-cpick summary small{color:var(--dim);font-weight:700}.ah-cpick[open] .ah-pick{margin:10px 0}
/* the status badge must never pick up the chart ".nodata" overlay styles (also fixes the Forex Heat Map badge) */
.hm-badge.nodata{position:static;inset:auto;display:inline-flex;flex-direction:row;justify-content:flex-start;text-align:left;padding:6px 12px;gap:8px;z-index:auto}
/* @@HEATMAPS-CSS-END */
/* @@HISTORY-CSS-START */
/* ===== Trading History · Beyond 2026 (cinematic overlay) ===== */
/* overlay */
body.hx-lock{overflow:hidden}
.hx-ov{position:fixed;inset:0;z-index:9999;background:#03030A;color:#fff;overflow:hidden;animation:hxIn .6s ease}
@keyframes hxIn{from{opacity:0}}
.hx-cv{position:absolute;inset:0;width:100%;height:100%}
.hx-vig{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 45%,rgba(0,0,0,.75) 100%)}
.hx-stage{position:absolute;inset:0;display:grid;place-items:center;text-align:center;padding:24px;pointer-events:none}
.hx-stage>*{grid-area:1/1}
.hx-title{opacity:0;transform:scale(1.06);filter:blur(10px);transition:opacity 1.1s ease,transform 2.4s cubic-bezier(.2,.7,.2,1),filter 1.2s ease}
.hx-title.on{opacity:1;transform:none;filter:none}
.hx-title p{margin:0 0 14px;font:800 clamp(10px,1.3vw,13px) var(--display);letter-spacing:.6em;color:#9FC1FF}
.hx-title h2{margin:0;font:800 clamp(34px,8vw,96px)/1 var(--display);letter-spacing:.04em;background:linear-gradient(100deg,#E9DEFF,#9B7BFF 45%,#3DA2FF);-webkit-background-clip:text;background-clip:text;color:transparent;text-shadow:0 0 60px rgba(139,92,246,.35)}
.hx-title h3{margin:16px 0 0;font:700 clamp(12px,2vw,20px) var(--display);letter-spacing:.45em;color:#D6D2FF}
.hx-year{opacity:0;font:800 clamp(44px,11vw,140px)/1 var(--display);letter-spacing:.02em;font-variant-numeric:tabular-nums;color:rgba(230,225,255,.92);text-shadow:0 0 40px rgba(155,92,255,.6),0 0 90px rgba(61,123,255,.4);transition:opacity .6s}
.hx-year.on{opacity:.9}.hx-year.now{color:#fff;text-shadow:0 0 50px rgba(61,162,255,.9),0 0 120px rgba(155,92,255,.6)}
.hx-msg{max-width:min(980px,92vw);margin:0;font:600 clamp(20px,3.6vw,44px)/1.25 var(--body);letter-spacing:.01em;color:#F3F0FF;opacity:0;text-shadow:0 2px 30px rgba(10,10,40,.9),0 0 40px rgba(123,104,255,.35)}
.hx-msg.on{animation:hxMsg 1.6s cubic-bezier(.2,.7,.2,1) forwards}
.hx-msg.big{font-size:clamp(20px,3.2vw,40px)}.hx-msg b{font-family:var(--display);font-weight:800;letter-spacing:.06em;background:linear-gradient(100deg,#D9C8FF,#8B7BFF 50%,#5CB6FF);-webkit-background-clip:text;background-clip:text;color:transparent}
@keyframes hxMsg{0%{opacity:0;filter:blur(12px);letter-spacing:.12em;transform:translateY(10px)}100%{opacity:1;filter:none;letter-spacing:.01em;transform:none}}
.hx-logo{opacity:0;visibility:hidden;display:flex;flex-direction:column;align-items:center;transform:translateY(-4vh)}
.hx-logo.on{opacity:1;visibility:visible;transition:opacity .4s}
.hx-logo svg{width:min(300px,52vw);height:auto;overflow:visible;filter:drop-shadow(0 0 22px rgba(139,92,246,.75)) drop-shadow(0 0 60px rgba(61,123,255,.45))}
.hx-logo path{stroke-dasharray:100;stroke-dashoffset:100}
.hx-logo.on path{animation:hxDraw 2.6s cubic-bezier(.65,0,.35,1) .1s forwards}
@keyframes hxDraw{to{stroke-dashoffset:0}}
/* padding-left = letter-spacing: wide letter-spacing adds space after the LAST letter too, which pushed these centred titles off-centre */
.hx-word{margin:22px 0 0;font:800 clamp(30px,7vw,84px)/1 var(--display);letter-spacing:.14em;padding-left:.14em;opacity:0}
.hx-word span{background:linear-gradient(100deg,#fff 10%,#CDBDFF 45%,#7FB8FF 90%);background-size:200% 100%;-webkit-background-clip:text;background-clip:text;color:transparent}
.hx-logo.on .hx-word{animation:hxWord 2.2s cubic-bezier(.2,.7,.2,1) 1.6s forwards}.hx-logo.on .hx-word span{animation:hxSheen 5s ease-in-out 3s infinite}
@keyframes hxWord{0%{opacity:0;letter-spacing:.6em;filter:blur(14px)}100%{opacity:1;letter-spacing:.14em;filter:none}}
@keyframes hxSheen{0%,100%{background-position:0 0}50%{background-position:100% 0}}
.hx-sub{margin:18px 0 0;font:700 clamp(11px,1.8vw,18px) var(--display);letter-spacing:.42em;padding-left:.42em;color:#BFD3FF;opacity:0}
.hx-logo.on .hx-sub{animation:hxFade 1.6s ease 3.2s forwards}
.hx-note{margin:18px 0 0;font-size:clamp(12px,1.3vw,14px);color:rgba(214,210,255,.7);opacity:0}.hx-logo.on .hx-note{animation:hxFade 1.4s ease 4.8s forwards}
@keyframes hxFade{to{opacity:1}}
.hx-end{display:flex;flex-wrap:wrap;gap:10px;justify-content:center;margin-top:26px;opacity:0;pointer-events:none;transition:opacity .8s}
.hx-done .hx-end{opacity:1;pointer-events:auto}
.hx-btn{display:inline-flex;align-items:center;min-height:44px;padding:0 18px;border-radius:12px;border:1px solid rgba(190,180,255,.35);background:rgba(20,20,48,.6);color:#fff;font:700 14px var(--body);text-decoration:none;cursor:pointer;backdrop-filter:blur(6px)}
