/* @@EVOLUTION-CSS-START */
/* ===== The Evolution of Trading — 5000 Years of Trading History ===== */
.evo{padding-top:24px;padding-bottom:34px}
.evo-hero{display:flex;justify-content:space-between;align-items:flex-end;gap:18px;flex-wrap:wrap;margin-bottom:14px}
.evo-hero h1{font-family:var(--display);font-weight:700;font-size:clamp(28px,4.6vw,52px);line-height:1.05;margin:0;background:linear-gradient(100deg,#fff 30%,#CDBDFF 60%,#8FC3FF);-webkit-background-clip:text;background-clip:text;color:transparent}
.evo-sub{margin:6px 0 10px;font:700 clamp(12px,1.5vw,16px) var(--display);letter-spacing:.3em;color:#9FC1FF;text-transform:uppercase}
.evo-hero .mut{max-width:640px;margin:0}
.evo-hacts{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}
.evo-stats{display:flex;gap:10px;margin:0;flex-wrap:wrap}.evo-stats div{padding:10px 14px;border-radius:14px;border:1px solid var(--line);background:linear-gradient(180deg,rgba(139,92,246,.1),rgba(61,123,255,.04));min-width:96px}
.evo-stats dt{font-size:10px;font-weight:800;letter-spacing:.1em;overflow-wrap:anywhere;color:var(--dim);text-transform:uppercase}.evo-stats dd{margin:3px 0 0;font-weight:800;font-size:15px;white-space:nowrap}
.evo-legend{list-style:none;margin:0 0 12px;padding:0;display:flex;flex-wrap:wrap;gap:6px 14px;font-size:12px;color:var(--muted)}.evo-legend li{display:inline-flex;align-items:center;gap:6px}.evo-legend i{width:9px;height:9px;border-radius:50%;background:var(--tc);box-shadow:0 0 8px var(--tc)}
.evo-type{display:inline-block;margin-left:8px;padding:2px 8px;border-radius:999px;font:800 9.5px var(--body);letter-spacing:.08em;text-transform:uppercase;color:var(--tc);border:1px solid color-mix(in srgb,var(--tc) 55%,transparent);background:color-mix(in srgb,var(--tc) 12%,transparent);vertical-align:middle;white-space:nowrap}
.evo-type.t-future{--tc:#7FB8FF}
/* chapter rail */
.evo-rail{position:relative;margin:0 0 16px;padding:8px;border-radius:18px;background:var(--charcoal);border:1px solid var(--line);overflow-x:auto;scrollbar-width:thin;scroll-snap-type:x proximity}
.evo-rail ol{list-style:none;margin:0;padding:0;display:grid;grid-auto-flow:column;grid-auto-columns:126px;gap:4px;position:relative}
.evo-rail ol::before{content:"";position:absolute;left:18px;right:18px;top:19px;height:2px;background:linear-gradient(90deg,rgba(155,92,255,.15),rgba(61,162,255,.35));pointer-events:none}
.evo-rail li{scroll-snap-align:center}
.evo-node{position:relative;width:100%;display:flex;flex-direction:column;align-items:flex-start;gap:2px;padding:9px 10px;border-radius:12px;border:1px solid transparent;background:none;color:var(--muted);font:inherit;text-align:left;cursor:pointer;transition:background .2s,color .2s,border-color .2s}
.evo-node i{width:10px;height:10px;border-radius:50%;background:#2c2d44;border:2px solid var(--tc);margin-bottom:5px;transition:background .3s,box-shadow .3s}
.evo-node b{font:800 10px var(--display);letter-spacing:.08em;color:var(--dim)}.evo-node span{font-weight:800;font-size:13px;color:inherit;line-height:1.2}.evo-node small{font-size:10.5px;color:var(--dim);line-height:1.25}
.evo-node:hover{color:var(--text);background:rgba(255,255,255,.03)}
.evo-node.done i{background:var(--tc)}
.evo-node.on{color:#fff;background:rgba(139,92,246,.2);border-color:rgba(155,92,255,.5)}.evo-node.on i{background:var(--tc);box-shadow:0 0 0 4px rgba(155,92,255,.25),0 0 14px var(--tc)}.evo-node.on b{color:#CDBDFF}
.evo-node.evo-fut span{background:linear-gradient(100deg,#D9C8FF,#7FB8FF);-webkit-background-clip:text;background-clip:text;color:transparent}.evo-node.evo-fut.on{background:linear-gradient(120deg,rgba(155,92,255,.3),rgba(61,123,255,.25))}
/* stage */
.evo-stage{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:16px;align-items:stretch;scroll-margin-top:calc(var(--nav-h) + 12px)}
.evo-scene{position:relative;min-height:480px;min-width:0;border-radius:22px;overflow:hidden;border:1px solid rgba(155,92,255,.35);background:#06061a;box-shadow:0 20px 33px rgba(30,20,90,.25),inset 0 0 0 1px rgba(255,255,255,.03)}
.evo-scene canvas{position:absolute;inset:0;width:100%;height:100%}
.evo-sceneyear{position:absolute;left:18px;top:14px;right:18px;pointer-events:none}
.evo-sceneyear span{display:inline-block;font:800 clamp(16px,2.4vw,28px) var(--display);letter-spacing:.03em;color:#fff;text-shadow:0 0 14px rgba(155,92,255,.38),0 0 32px rgba(61,123,255,.22)}
.evo-sceneyear.in span{animation:evoYear 1.1s cubic-bezier(.2,.7,.2,1)}
@keyframes evoYear{from{opacity:0;letter-spacing:.3em;filter:blur(8px)}}
.evo-illus{position:absolute;right:12px;bottom:10px;font:700 9px var(--display);letter-spacing:.14em;text-transform:uppercase;color:rgba(200,195,255,.45);pointer-events:none}
.evo-autobar{position:absolute;left:0;right:0;bottom:0;height:3px;background:rgba(255,255,255,.05)}.evo-autobar i{display:block;height:100%;width:0;background:linear-gradient(90deg,#9B5CFF,#3DA2FF)}
.evo-copy{padding:20px 22px;border-radius:22px;border:1px solid var(--line);background:linear-gradient(170deg,rgba(139,92,246,.12),rgba(61,123,255,.05) 60%,rgba(255,255,255,.01));display:flex;flex-direction:column;gap:10px;min-width:0}
.evo-copy.in>*{animation:evoIn .8s cubic-bezier(.2,.7,.2,1) both}
.evo-copy.in>*:nth-child(2){animation-delay:.05s}.evo-copy.in>*:nth-child(3){animation-delay:.1s}.evo-copy.in>*:nth-child(4){animation-delay:.15s}.evo-copy.in>*:nth-child(5){animation-delay:.22s}.evo-copy.in>*:nth-child(6){animation-delay:.3s}.evo-copy.in>*:nth-child(7){animation-delay:.38s}.evo-copy.in>*:nth-child(8){animation-delay:.46s}
@keyframes evoIn{from{opacity:0;transform:translateY(12px);filter:blur(4px)}}
