.pt-qres{font-size:16px}
/* candlestick SVG */
.pc-svg{display:block;width:100%;height:auto}
.pc-k line{stroke-width:1.3}.pc-k.up line{stroke:#2EE6A8}.pc-k.dn line{stroke:#FF5C7A}
.pc-k.up rect:not(.pc-hit){fill:#2EE6A8}.pc-k.dn rect:not(.pc-hit){fill:#FF5C7A}
.pc-k.ctx{opacity:.5}.pc-k.conf rect:not(.pc-hit){fill:transparent;stroke-dasharray:3 2;stroke-width:1.4}.pc-k.conf.up rect:not(.pc-hit){stroke:#2EE6A8}.pc-k.conf.dn rect:not(.pc-hit){stroke:#FF5C7A}
.pc-hit{fill:transparent}
.pc-k.ans rect:not(.pc-hit){stroke:#fff;stroke-width:2.2}.pc-k.miss rect:not(.pc-hit){stroke:#FFC24B;stroke-width:2.2}
.pc-zone{fill:rgba(139,92,246,.12);stroke:rgba(155,92,255,.5);stroke-dasharray:4 3}
.pc-lv line{stroke-width:1.3;stroke-dasharray:6 4}.pc-lv text{font:600 11px var(--body);fill:var(--muted)}
.pc-lv.entry line{stroke:#7FB8FF}.pc-lv.entry text{fill:#7FB8FF}.pc-lv.stop line{stroke:#FF5C7A}.pc-lv.stop text{fill:#FF8FA3}.pc-lv.tgt line{stroke:#2EE6A8}.pc-lv.tgt text{fill:#9FF5D6}
.pc-tl{stroke:#B26BFF;stroke-width:1.6}.pc-tl.res{stroke:#FF8FA3}.pc-tl.sup{stroke:#2EE6A8}.pc-tl.neck{stroke:#FFC24B}
.pc-tlt{font:600 11px var(--body);fill:#CDBDFF}.pc-tlt.neck{fill:#FFD48A}
.pc-mk circle{fill:none;stroke:#fff;stroke-width:1.6}.pc-mk text{font:700 11px var(--body);fill:#fff}.pc-mk.fk text{fill:#FFD48A}.pc-mk.cf text{fill:#9FF5D6}
.pc-wm{font:600 10.5px var(--body);fill:var(--dim);letter-spacing:.04em}
.pt-path{fill:none;stroke:#9C9EB8;stroke-width:1.6}.pt-path.post.up{stroke:#2EE6A8}.pt-path.post.down{stroke:#FF5C7A}
/* animation (all of it is skipped with prefers-reduced-motion) */
.pc-anim .pc-k{opacity:0;transform:translateY(6px);transition:opacity .28s ease,transform .28s ease}
.pc-anim .pc-k.on{opacity:1;transform:none}.pc-anim .pc-k.ctx.on{opacity:.5}
.pc-anim .pc-late,.pc-anim .pc-mk.late{opacity:0;transition:opacity .4s ease}.pc-anim.done .pc-late,.pc-anim.done .pc-mk.late{opacity:1}
.pc-anim .pc-zone{opacity:0;transition:opacity .3s}.pc-anim.mid .pc-zone{opacity:1}
.pc-anim .pc-tl.mid,.pc-anim .pc-tlt.mid,.pc-anim .pc-mk.mid{opacity:0;transition:opacity .4s}.pc-anim.mid .pc-tl.mid,.pc-anim.mid .pc-tlt.mid,.pc-anim.mid .pc-mk.mid{opacity:1}
.pc-ctrl{display:flex;flex-wrap:wrap;gap:8px;align-items:center}
.pc-ctrl .ac-btn{display:inline-flex;align-items:center;gap:6px;min-height:40px}.pc-ctrl svg{width:16px;height:16px}
.pc-speed{display:flex;align-items:center;gap:6px;font-size:13px;color:var(--muted)}.pc-speed select{height:40px;border-radius:10px;border:1px solid var(--line-2);background:var(--obsidian);color:var(--text);padding:0 8px}
.rv{opacity:0;transform:translateY(10px);transition:opacity .45s ease,transform .45s ease}.rv.in{opacity:1;transform:none}
@media (prefers-reduced-motion:reduce){ .rv{opacity:1;transform:none} .pc-anim .pc-k,.pc-anim .pc-late,.pc-anim .pc-zone,.pc-anim .pc-mk,.pc-anim .pc-tl,.pc-anim .pc-tlt{opacity:1!important;transform:none!important} }
@media (max-width:760px){ .pt-sec2{grid-template-columns:1fr} .pt-trade dl{grid-template-columns:1fr} .pt-kpis{grid-template-columns:1fr 1fr} .pt-search{justify-content:flex-start} .pt-search input{width:100%} }
@media (max-width:420px){ .pt-grid{grid-template-columns:repeat(2,minmax(0,1fr))} .pt-card{padding:8px} .pt-opts.two{grid-template-columns:1fr 1fr} }
/* White Monochrome (2026-10-27): context candles were faded to 50 % for the dark design; on white that washes them out, so they stay a little stronger */
html[data-theme="light"] .pc-k.ctx,html[data-theme="light"] .pc-anim .pc-k.ctx.on{opacity:.8!important}
html:root[data-theme="light"] .pc-zone{fill:rgba(0,0,0,.035);stroke:rgba(0,0,0,.3)}   /* the pattern's highlight box: a light outline, not a grey block */
