.vct-cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:10px}.vct-c{border:1px solid var(--line);border-radius:12px;padding:10px 12px;background:rgba(255,255,255,.02)}.vct-c h4{margin:0 0 6px;font-size:13px;color:#CDBDFF}.vct-c p{margin:4px 0}
