  .vct-dom,.vct-cols{grid-template-columns:1fr}.vct-ms{grid-template-columns:1fr 1fr}
}

/* Vision Trading Terminal — maintenance screen (VC_TERMINAL_MAINTENANCE in vc-site.js) */
.vc-mnt{position:relative;overflow:hidden;margin:18px auto 40px;max-width:760px;padding:clamp(28px,6vw,56px) clamp(18px,5vw,48px);text-align:center;border-radius:22px;
  background:radial-gradient(600px 260px at 50% -10%,rgba(47,168,255,.16),transparent 70%),radial-gradient(500px 300px at 100% 110%,rgba(139,92,246,.18),transparent 70%),#04060c;
  border:1px solid rgba(110,140,230,.22);box-shadow:0 0 70px rgba(47,168,255,.08),inset 0 0 0 1px rgba(139,92,246,.06)}
.vc-mnt-orb{position:relative;width:96px;height:96px;margin:0 auto 18px;display:grid;place-items:center;color:#8fd2ff}
.vc-mnt-orb span{position:absolute;inset:0;border-radius:50%;border:2px solid transparent;border-top-color:#2fa8ff;border-right-color:rgba(139,92,246,.8);animation:vcMntSpin 3.2s linear infinite}
.vc-mnt-orb span+span{inset:12px;border-top-color:#8b5cf6;border-right-color:rgba(47,168,255,.6);animation-duration:2.2s;animation-direction:reverse}
.vc-mnt-orb svg{filter:drop-shadow(0 0 10px rgba(47,168,255,.6))}
.vc-mnt-k{margin:0;font-size:11px;letter-spacing:.24em;font-weight:700;color:#8b5cf6}
.vc-mnt h1{margin:8px 0 14px;font-size:clamp(24px,5vw,40px);letter-spacing:.06em;background:linear-gradient(90deg,#e8eeff,#8fd2ff 45%,#b9a2ff);-webkit-background-clip:text;background-clip:text;color:transparent}
.vc-mnt-st{display:inline-flex;align-items:center;gap:8px;margin:0 0 20px;padding:7px 16px;border-radius:999px;font-size:12.5px;font-weight:800;letter-spacing:.16em;color:#ffd48a;background:rgba(255,194,75,.1);border:1px solid rgba(255,194,75,.35)}
.vc-mnt-st i{width:8px;height:8px;border-radius:50%;background:#ffc24b;box-shadow:0 0 10px #ffc24b;animation:vcMntPulse 1.6s ease-in-out infinite}
.vc-mnt-msg{max-width:520px;margin:0 auto 10px;color:#b8c4e6;line-height:1.65;font-size:15.5px}
.vc-mnt-bar{position:relative;height:4px;max-width:320px;margin:26px auto 14px;border-radius:4px;background:rgba(110,140,230,.15);overflow:hidden}
.vc-mnt-bar span{position:absolute;top:0;bottom:0;width:38%;border-radius:4px;background:linear-gradient(90deg,transparent,#2fa8ff,#8b5cf6,transparent);animation:vcMntScan 2.4s ease-in-out infinite}
.vc-mnt-soon{margin:0;font-size:12px;letter-spacing:.3em;font-weight:800;color:#7dc4ff}
.vc-mnt-cta{justify-content:center;margin-top:26px}
@keyframes vcMntSpin{to{transform:rotate(360deg)}}
@keyframes vcMntPulse{50%{opacity:.35}}
@keyframes vcMntScan{0%{left:-40%}100%{left:100%}}
@media (prefers-reduced-motion:reduce){ .vc-mnt-orb span,.vc-mnt-st i,.vc-mnt-bar span{animation:none} }
.vc-mnt-note{max-width:520px;margin:18px auto 0;color:#8ea0c9;font-size:13.5px;line-height:1.6}
