.cm a{color:inherit}
.cm .sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.cm-i{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round;flex:none}
.cm-load{padding:28px;text-align:center;color:var(--cm-mut)}
.cm-mut{color:var(--cm-mut)} .cm-fine{font-size:12px;color:var(--cm-mut);line-height:1.5}
.cm-btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;min-height:38px;padding:0 18px;border-radius:999px;border:1px solid transparent;background:var(--grad);color:#fff;font:700 14px/1 var(--body);cursor:pointer;text-decoration:none;white-space:nowrap}
.cm-btn:hover{filter:brightness(1.08)} .cm-btn:disabled{opacity:.45;cursor:not-allowed;filter:none}
.cm-btn.ghost{background:transparent;border-color:var(--cm-line2);color:var(--cm-text)} .cm-btn.ghost:hover{background:var(--cm-hover)}
.cm-btn.sm{min-height:32px;padding:0 14px;font-size:13px} .cm-btn.danger{background:rgba(255,79,123,.14);border-color:rgba(255,79,123,.5);color:#FF8FA8}
.cm-ib{display:inline-grid;place-items:center;width:36px;height:36px;border-radius:50%;border:0;background:transparent;color:var(--cm-mut);cursor:pointer;padding:0}
.cm-ib:hover{background:var(--cm-hover);color:var(--cm-text)}
.cm-link{border:0;background:none;color:var(--cm-acc);font:600 13px var(--body);cursor:pointer;padding:6px 0}
.cm :focus-visible{outline:2px solid var(--cyan);outline-offset:2px}

/* left column */
.cm-left{position:sticky;top:var(--nav-h);height:calc(100vh - var(--nav-h));display:flex;flex-direction:column;gap:6px;padding:18px 0 16px;overflow-y:auto;scrollbar-width:none}
.cm-brand{display:flex;align-items:center;gap:10px;padding:4px 10px 14px;text-decoration:none}
.cm-logo{display:grid;place-items:center;width:40px;height:40px;border-radius:12px;background:var(--grad);color:#fff;flex:none}
.cm-brand b{display:block;font:800 13px var(--display);letter-spacing:.06em}.cm-brand small{display:block;font-size:11.5px;color:var(--cm-mut);margin-top:3px}
.cm-nav{display:flex;flex-direction:column;gap:2px}
.cm-nav a{position:relative;display:flex;align-items:center;gap:14px;padding:11px 14px;border-radius:999px;text-decoration:none;font-weight:700;font-size:16px;color:var(--cm-text)}
.cm-nav a:hover{background:var(--cm-hover)} .cm-nav a.on{background:rgba(124,107,255,.14)} .cm-nav a.on .cm-i{color:var(--cm-acc);stroke-width:2.3}
.cm-nav .cm-i{width:23px;height:23px}
.cm-dot{position:absolute;left:28px;top:5px;min-width:18px;height:18px;padding:0 5px;border-radius:999px;background:var(--cm-blue);color:#fff;font:800 10.5px/18px var(--body);text-align:center;font-style:normal}
.cm-postbtn{display:flex;align-items:center;justify-content:center;gap:8px;margin:10px 4px 0;min-height:48px;border:0;border-radius:999px;background:var(--grad);color:#fff;font:800 16px var(--body);cursor:pointer;box-shadow:0 10px 30px -12px rgba(124,107,255,.8)}
.cm-postbtn:hover{filter:brightness(1.08)}
.cm-mecard{margin-top:auto;padding:10px 6px 0}
.cm-me{display:flex;align-items:center;gap:10px;padding:8px;border-radius:999px;text-decoration:none}.cm-me:hover{background:var(--cm-hover)}
.cm-me .cm-nm{flex-direction:column;align-items:flex-start;gap:0;min-width:0}

/* center */
.cm-main{border-left:1px solid var(--cm-line);border-right:1px solid var(--cm-line);min-width:0;min-height:calc(100vh - var(--nav-h));padding-bottom:40px}
.cm-head{position:sticky;top:var(--nav-h);z-index:5;display:flex;align-items:center;gap:10px;padding:12px 16px;background:color-mix(in srgb,var(--cm-bg) 86%,transparent);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);border-bottom:1px solid var(--cm-line)}
.cm-head h1{margin:0;font:800 19px/1.2 var(--body);overflow-wrap:anywhere}.cm-head p{margin:2px 0 0;font-size:13px;color:var(--cm-mut)}
.cm-tabs{display:flex;align-items:stretch;border-bottom:1px solid var(--cm-line);position:sticky;top:calc(var(--nav-h) + 53px);z-index:4;background:color-mix(in srgb,var(--cm-bg) 90%,transparent);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px)}
.cm-tabs button[role=tab]{flex:1;position:relative;padding:15px 8px;border:0;background:none;color:var(--cm-mut);font:700 15px var(--body);cursor:pointer}
.cm-tabs button[role=tab]:hover{background:var(--cm-hover)} .cm-tabs button.on{color:var(--cm-text)}
.cm-tabs button.on::after{content:"";position:absolute;left:50%;bottom:0;width:56px;height:4px;margin-left:-28px;border-radius:4px;background:var(--grad)}
.cm-tabs .cm-ib{align-self:center;margin:0 8px}
.cm-join{display:flex;align-items:center;gap:16px;justify-content:space-between;margin:14px 16px;padding:16px 18px;border-radius:18px;border:1px solid var(--cm-line2);background:linear-gradient(135deg,rgba(124,107,255,.12),rgba(47,140,255,.06))}
.cm-join p{margin:4px 0 0;color:var(--cm-mut);font-size:14px;line-height:1.5}
.cm-empty{padding:38px 22px;text-align:center;color:var(--cm-mut);line-height:1.55}.cm-empty b{color:var(--cm-text)}.cm-empty .cm-btn{margin-top:10px}
.cm-end{text-align:center;color:var(--cm-mut);font-size:13px;padding:22px}

/* composer */
.cm-compose{display:grid;grid-template-columns:auto minmax(0,1fr);gap:12px;padding:14px 16px;border-bottom:1px solid var(--cm-line)}
.cm-compose.modal{border:0;padding:6px 0 0}
.cm-compose textarea{width:100%;min-height:52px;resize:none;border:0;background:transparent;color:var(--cm-text);font:500 18px/1.45 var(--body);padding:8px 0;outline:none}
.cm-compose textarea::placeholder{color:var(--cm-mut)}
.cm-cbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding-top:10px;border-top:1px solid var(--cm-line)}
.cm-attach{color:var(--cm-acc)}.cm-attach.off{opacity:.4;pointer-events:none}
.cm-quota{font-size:12.5px;font-weight:700;color:var(--cm-mut);padding:4px 10px;border-radius:999px;background:var(--cm-hover)}.cm-quota.full{color:#FF8FA8;background:rgba(255,79,123,.1)}
.cm-count{margin-left:auto;font-size:12px;color:var(--cm-mut);font-variant-numeric:tabular-nums}.cm-count.warn{color:var(--amber)}
.cm-limit{margin:6px 0 4px;padding:10px 12px;border-radius:12px;background:rgba(255,79,123,.1);color:#FF9CB2;font-weight:600;font-size:14px}
.cm-thumbs{display:flex;gap:8px;flex-wrap:wrap}.cm-thumbs:empty{display:none}
.cm-th{position:relative;width:96px;height:96px;border-radius:14px;overflow:hidden;background:var(--cm-card2);display:grid;place-items:center}
.cm-th img{width:100%;height:100%;object-fit:cover}
.cm-thx{position:absolute;top:5px;right:5px;width:26px;height:26px;border-radius:50%;border:0;background:rgba(0,0,0,.7);color:#fff;display:grid;place-items:center;cursor:pointer;padding:0}.cm-thx .cm-i{width:15px;height:15px}
.cm-spin{width:24px;height:24px;border-radius:50%;border:3px solid var(--cm-line2);border-top-color:var(--cm-acc);animation:cmSpin .8s linear infinite}
@keyframes cmSpin{to{transform:rotate(360deg)}}

/* posts */
.cm-post{display:grid;grid-template-columns:auto minmax(0,1fr);gap:12px;padding:14px 16px 6px;border-bottom:1px solid var(--cm-line);transition:background .15s;animation:cmIn .25s ease}
.cm-post:not(.full):hover{background:var(--cm-hover)}
@keyframes cmIn{from{opacity:0;transform:translateY(4px)}}
.cm-av{display:grid;place-items:center;border-radius:50%;object-fit:cover;color:#fff;font-weight:800;flex:none;background:var(--cm-card2)}
.cm-pav{align-self:start;text-decoration:none;border-radius:50%}
.cm-pb{min-width:0}
.cm-ph{display:flex;align-items:center;gap:6px;min-width:0;font-size:15px;line-height:1.3}
.cm-nm{display:inline-flex;align-items:center;gap:5px;min-width:0;text-decoration:none;overflow:hidden}
.cm-nm b{font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
.cm-nm:hover b{text-decoration:underline}
.cm-un{color:var(--cm-mut);font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
.cm-sep,.cm-time,.cm-ed{color:var(--cm-mut);white-space:nowrap;text-decoration:none;font-size:14px}.cm-time:hover{text-decoration:underline}.cm-ed{font-size:12px}
.cm-pmore{margin-left:auto;width:32px;height:32px;margin-right:-6px}
.cm-ver{display:inline-grid;place-items:center;color:#fff;flex:none}
.cm-ver{margin-left:3px;vertical-align:-3px;cursor:help}.cm-ver svg{width:17px;height:17px;display:block}
/* the badge colours never follow the theme (scripts/theme-system.mjs skips :root:root rules) */
:root:root .cm-ver .vb-seal{fill:#0095F6;stroke:#0095F6}:root:root .cm-ver .vb-tick{fill:none;stroke:#fff}
.cm-ver.big{margin:0}
/* stacked name cards (my card, suggestions): the badge stays on the name's line, the @username below */
.cm-me .cm-nm,.cm-sug .cm-nm{display:grid;grid-template-columns:minmax(0,max-content) auto;justify-content:start;column-gap:2px}.cm-me .cm-un,.cm-sug .cm-un{grid-column:1/-1}.cm-ver.big svg{width:64px;height:64px}.cm-disc .cm-ver svg,.cm-nl .cm-ver svg{width:14px;height:14px}
.cm-txt{margin:4px 0 0;font-size:15.5px;line-height:1.55;white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word}
.cm-post.full .cm-txt{font-size:18px}
.cm-clamp{display:-webkit-box;-webkit-line-clamp:6;-webkit-box-orient:vertical;overflow:hidden}
.cm-showmore{border:0;background:none;color:var(--cm-acc);font:700 14px var(--body);padding:4px 0;cursor:pointer}
.cm .cm-url,.cm .cm-tag,.cm .cm-men{color:var(--cm-acc);text-decoration:none;font-weight:600}.cm .cm-url:hover,.cm .cm-tag:hover,.cm .cm-men:hover{text-decoration:underline}
.cm-imgs{display:grid;gap:3px;margin-top:10px;border-radius:16px;overflow:hidden;border:1px solid var(--cm-line)}
.cm-imgs.n1{grid-template-columns:1fr}.cm-imgs.n2{grid-template-columns:1fr 1fr}.cm-imgs.n3{grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr}.cm-imgs.n4{grid-template-columns:1fr 1fr}
.cm-imgs.n3 .cm-img:first-child{grid-row:1/3}
.cm-img{display:block;padding:0;border:0;background:var(--cm-card2);cursor:zoom-in;aspect-ratio:16/10;overflow:hidden}
.cm-imgs.n1 .cm-img{aspect-ratio:auto;max-height:520px}.cm-imgs.n3 .cm-img:first-child{aspect-ratio:auto}
.cm-img img{width:100%;height:100%;object-fit:cover;display:block}.cm-imgs.n1 .cm-img img{max-height:520px;object-fit:contain;background:#05050a}
.cm-full-time{margin:12px 0 0;padding-bottom:10px;border-bottom:1px solid var(--cm-line);color:var(--cm-mut);font-size:14px}
.cm-acts{display:flex;justify-content:space-between;max-width:430px;margin:6px 0 0 -8px}
.cm-acts.sm{justify-content:flex-start;gap:14px}
.cm-act{display:inline-flex;align-items:center;gap:5px;min-height:34px;padding:0 8px;border:0;border-radius:999px;background:none;color:var(--cm-mut);font:600 13px var(--body);cursor:pointer;text-decoration:none}
.cm-act .cm-i{width:18px;height:18px}
.cm-act:hover{color:var(--cm-acc);background:rgba(124,107,255,.1)}
.cm-like:hover,.cm-like.on{color:var(--cm-like)}.cm-like:hover{background:rgba(255,79,123,.1)}.cm-like.on .cm-i{fill:var(--cm-like)}
.cm-like.on .cm-i{animation:cmPop .3s ease}@keyframes cmPop{50%{transform:scale(1.25)}}
.cm-bm.on{color:var(--cm-acc)}.cm-bm.on .cm-i{fill:var(--cm-acc)}

/* comments */
.cm-creply{padding:12px 16px;border-bottom:1px solid var(--cm-line)}
.cm-cform{display:flex;align-items:flex-start;gap:10px}
.cm-cform textarea{flex:1;min-height:40px;resize:none;border:1px solid var(--cm-line2);border-radius:14px;background:var(--cm-card);color:var(--cm-text);font:500 15px/1.45 var(--body);padding:9px 12px;outline:none}
.cm-cform textarea:focus{border-color:var(--cm-acc)}
.cm-cform.sm{margin:8px 0 4px}
.cm-cgrp{border-bottom:1px solid var(--cm-line);padding:4px 0}
.cm-cmt{display:grid;grid-template-columns:auto minmax(0,1fr);gap:10px;padding:10px 16px}
.cm-cmt.rep{padding-left:58px;position:relative}
.cm-cmt.rep::before{content:"";position:absolute;left:33px;top:0;bottom:0;width:2px;background:var(--cm-line2)}
.cm-cmt.gone{display:block;padding:10px 16px 10px 58px;font-size:14px}
.cm-cmb{min-width:0}.cm-cmb .cm-txt{font-size:15px}
.cm-to{display:block;font-size:12.5px;color:var(--cm-mut)}
.cm-showreps{margin:0 0 8px 58px;border:0;background:none;color:var(--cm-acc);font:700 13.5px var(--body);cursor:pointer;padding:4px 0}

/* profile */
.cm-prof{border-bottom:1px solid var(--cm-line);padding-bottom:14px}
.cm-cover{height:180px;background:linear-gradient(120deg,#2a1e5c,#123a7a 55%,#0c5f7a);background-size:cover;background-position:center}
.cm-cover.sm{height:110px;border-radius:14px;margin-bottom:-36px}
.cm-pt{display:flex;align-items:flex-end;justify-content:space-between;padding:0 16px;margin-top:-48px}
.cm-pt .cm-av{border:4px solid var(--cm-bg)}
.cm-pacts{display:flex;gap:8px;align-items:center;padding-bottom:6px}
.cm-pn{display:flex;align-items:center;gap:6px;margin:10px 16px 0;font:800 21px var(--body)}
.cm-prof .cm-un{display:block;margin:2px 16px 0}
.cm-bio{margin:10px 16px 0;line-height:1.5;white-space:pre-wrap;overflow-wrap:anywhere}
.cm-joined{margin:8px 16px 0;font-size:14px}
.cm-stats{display:flex;flex-wrap:wrap;gap:6px 18px;margin:10px 16px 0;font-size:14px;color:var(--cm-mut)}.cm-stats b{color:var(--cm-text)}
.cm-subh{margin:0;padding:14px 16px;font:800 16px var(--body);border-bottom:1px solid var(--cm-line)}

/* explore, search, right column */
.cm-search{display:flex;align-items:center;gap:10px;padding:0 16px;min-height:46px;border-radius:999px;background:var(--cm-card2);border:1px solid transparent;color:var(--cm-mut)}
.cm-search:focus-within{border-color:var(--cm-acc);background:var(--cm-bg)}
.cm-search input{flex:1;min-width:0;border:0;background:transparent;color:var(--cm-text);font:500 15px var(--body);outline:none}
.cm-search.big{margin:14px 16px}
.cm-sec{padding:8px 16px 14px;border-bottom:1px solid var(--cm-line)}.cm-sec h2{font:800 17px var(--body);margin:8px 0 10px}
.cm-sec .cm-post{margin:0 -16px}
.cm-chips{display:flex;flex-wrap:wrap;gap:8px}
.cm .cm-chip{padding:8px 12px;border-radius:999px;background:var(--cm-card2);text-decoration:none;font-weight:700;color:var(--cm-acc)}.cm-chip small{color:var(--cm-mut);font-weight:500;margin-left:4px}
.cm-person{display:flex;align-items:center;gap:12px;padding:10px 0;text-decoration:none}.cm-person>span{flex:1;min-width:0;display:flex;flex-direction:column}
.cm-person small{color:var(--cm-mut);font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.cm-person em{font-style:normal;font-size:12.5px;color:var(--cm-mut);white-space:nowrap}
.cm-right{position:sticky;top:var(--nav-h);height:calc(100vh - var(--nav-h));overflow-y:auto;padding:14px 0 20px;display:flex;flex-direction:column;gap:14px;scrollbar-width:thin}
.cm-card{border:1px solid var(--cm-line);border-radius:18px;background:var(--cm-card);padding:14px 16px}
.cm-card h2{font:800 17px var(--body);margin:0 0 10px}
.cm-main .cm-card{margin:14px 16px}
.cm-trend{list-style:none;margin:0;padding:0}.cm-trend a{display:flex;flex-direction:column;padding:8px 0;text-decoration:none}.cm-trend a:hover b{text-decoration:underline}
.cm-trend small{font-size:12px;color:var(--cm-mut)}.cm-trend b{font-size:15px}
.cm-disc{display:block;padding:8px 0;text-decoration:none;border-top:1px solid var(--cm-line)}.cm-disc:first-of-type{border-top:0}
.cm-disc small{display:block;font-size:12px;color:var(--cm-mut)}.cm-disc span{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-size:14px;line-height:1.4}
.cm-rules{margin:0;padding-left:18px;display:grid;gap:6px;font-size:13.5px;line-height:1.45;color:var(--cm-mut)}.cm-rules.big{font-size:15px;color:var(--cm-text);gap:10px}
.cm-sug{display:flex;align-items:center;gap:10px;padding:7px 0}.cm-sug>a{flex:1;min-width:0;text-decoration:none}.cm-sug .cm-nm{flex-direction:column;align-items:flex-start;gap:0}

/* notifications */
.cm-note{display:flex;gap:12px;padding:14px 16px;border-bottom:1px solid var(--cm-line);text-decoration:none}.cm-note:hover{background:var(--cm-hover)}
.cm-note.new{background:rgba(124,107,255,.07)}
.cm-nic{display:grid;place-items:center;width:34px;height:34px;border-radius:50%;flex:none;color:var(--cm-acc);background:rgba(124,107,255,.12)}
.cm-nic.t-like,.cm-nic.t-comment_like{color:var(--cm-like);background:rgba(255,79,123,.12)}.cm-nic.t-like .cm-i,.cm-nic.t-comment_like .cm-i{fill:var(--cm-like)}
.cm-nic[class*="t-verify"]{color:var(--cm-blue);background:rgba(47,140,255,.12)}
.cm-nic.t-post_removed,.cm-nic.t-comment_removed,.cm-nic.t-warning,.cm-nic.t-suspended,.cm-nic.t-banned{color:var(--amber);background:rgba(255,194,75,.12)}
.cm-nb{min-width:0;display:flex;flex-direction:column;gap:4px;font-size:14.5px;line-height:1.4}.cm-nl{display:flex;align-items:center;gap:8px;min-width:0}.cm-nl>span{min-width:0;overflow-wrap:anywhere}
.cm-nt{color:var(--cm-mut);overflow-wrap:anywhere}.cm-nb small{color:var(--cm-mut);font-size:12.5px}

/* verified + settings */
.cm-vhero{display:flex;gap:18px;align-items:center;margin:16px;padding:22px;border-radius:20px;background:linear-gradient(135deg,rgba(47,140,255,.16),rgba(124,107,255,.12));border:1px solid rgba(47,140,255,.3)}
.cm-vhero h2{margin:0 0 6px;font:800 22px var(--body)}.cm-vhero p{margin:0;color:var(--cm-mut);line-height:1.5}
.cm-vbig .cm-i{width:64px;height:64px;fill:var(--cm-blue);stroke:#fff;stroke-width:1.3}
.cm-price{margin-top:10px!important;color:var(--cm-text)!important;font-size:17px}
.cm-what ul,.cm-plain{margin:0;padding-left:18px;display:grid;gap:8px;line-height:1.5;font-size:14.5px}.cm-what ul{list-style:none;padding:0}
.cm-ok,.cm-pend{margin:14px 16px;padding:12px 14px;border-radius:14px;display:flex;gap:8px;align-items:center;line-height:1.45}
.cm-ok{background:rgba(47,140,255,.12);border:1px solid rgba(47,140,255,.35)}.cm-ok .cm-i{fill:var(--cm-blue);stroke:#fff}
.cm-pend{background:rgba(255,194,75,.1);border:1px solid rgba(255,194,75,.35)}
.cm-steps{margin:0 0 12px;padding-left:20px;display:grid;gap:6px;line-height:1.5}
.cm-note2{padding:10px 12px;border-radius:12px;background:var(--cm-card2);white-space:pre-wrap;line-height:1.5}
.cm-pay{padding:10px 12px;border-radius:12px;border:1px solid var(--cm-line);margin:8px 0}.cm-pay p{margin:4px 0;overflow-wrap:anywhere}.cm-pay img{display:block;margin-top:8px;border-radius:10px;background:#fff;padding:6px}
.cm-hist{margin:14px 16px;color:var(--cm-mut);font-size:14px}.cm-hist summary{cursor:pointer;font-weight:700;color:var(--cm-text)}
.cm-seg{display:inline-flex;padding:4px;border-radius:999px;background:var(--cm-card2)}.cm-seg button{border:0;background:none;color:var(--cm-mut);font:700 14px var(--body);padding:8px 18px;border-radius:999px;cursor:pointer}.cm-seg button.on{background:var(--grad);color:#fff}
.cm-card.danger{border-color:rgba(255,79,123,.35)}

/* forms + modal */
.cm-form{display:grid;gap:12px}.cm-form h2{margin:0;font:800 20px var(--body)}
.cm-form label{display:grid;gap:6px;font-size:13.5px;font-weight:700}.cm-form label small{font-weight:500;color:var(--cm-mut)}
.cm-form input:not([type=radio]):not([type=file]),.cm-form textarea{width:100%;min-height:44px;border-radius:12px;border:1px solid var(--cm-line2);background:var(--cm-bg);color:var(--cm-text);font:500 15px var(--body);padding:10px 12px;outline:none}
.cm-form textarea{resize:vertical;line-height:1.45}
.cm-form input:focus,.cm-form textarea:focus{border-color:var(--cm-acc)}
.cm-form input[type=file]{font-size:13px;color:var(--cm-mut)}
.cm-pre{display:flex;align-items:center;border:1px solid var(--cm-line2);border-radius:12px;background:var(--cm-bg);padding-left:12px}.cm-pre i{font-style:normal;color:var(--cm-mut)}.cm-pre input{border:0!important;background:transparent!important}
.cm-err{margin:0;min-height:18px;color:#FF8FA8;font-weight:600;font-size:14px}
