.st-page{--st-bg:#04060c;--st-pan:#0a1022;--st-pan2:#0d1530;--st-line:rgba(110,140,230,.16);--st-txt:#dfe7ff;--st-mut:#8ea0c9;--st-blue:#2fa8ff;--st-pur:#8b5cf6;--st-up:#39ff88;--st-dn:#ff4d6d;--st-warn:#ffc85c;
