.st-ohlc b{color:var(--st-txt)}.st-ohlc span{color:var(--st-txt)}
.st-cnote{position:absolute;left:50%;top:44%;transform:translateX(-50%);color:var(--st-warn);font-size:13px;pointer-events:none;text-align:center}

/* order panel */
.st-op{overflow:auto}
.st-form{padding:10px 12px;display:flex;flex-direction:column;gap:10px}
.st-f{display:flex;flex-direction:column;gap:4px;font-size:12px;color:var(--st-mut);min-width:0}
.st-f small{font-size:10.5px;opacity:.85}
