.st-f input:focus,.st-f select:focus{outline:none;border-color:var(--st-blue);box-shadow:0 0 0 2px rgba(47,168,255,.2)}
.st-lots{display:grid;grid-template-columns:repeat(6,1fr);gap:3px}
.st-lots button{padding:5px 0}
.st-in2{display:flex;gap:4px}.st-in2 button{background:rgba(47,168,255,.12);border:1px solid rgba(47,168,255,.3);color:var(--st-blue);border-radius:8px;font:inherit;font-size:11px;padding:0 8px;cursor:pointer}
.st-row2{display:grid;grid-template-columns:1fr 1fr;gap:8px}
