.st-fine{font-size:11px;color:var(--st-mut);margin:0;line-height:1.5}

/* account strip + tabs */
.st-bot{margin-top:10px;overflow:hidden}
.st-acc{display:flex;flex-wrap:wrap;gap:6px 22px;padding:10px 14px;border-bottom:1px solid var(--st-line);font-variant-numeric:tabular-nums}
.st-acc>div small{display:block;font-size:10.5px;color:var(--st-mut);text-transform:uppercase;letter-spacing:.06em}.st-acc>div b{font-size:15px}
.st-mc{flex-basis:100%;margin:2px 0 0;color:var(--st-warn);font-size:12px}
.st-tabs{display:flex;gap:2px;padding:6px 8px 0;border-bottom:1px solid var(--st-line)}
