.st-tabs button[aria-selected=true]{color:var(--st-txt);border-bottom-color:var(--st-blue)}
.st-tbl{overflow-x:auto;max-height:420px;overflow-y:auto}
.st-tbl table{width:100%;border-collapse:collapse;font-size:12px;font-variant-numeric:tabular-nums;min-width:980px}
.st-tbl th{position:sticky;top:0;background:var(--st-pan2);color:var(--st-mut);font-weight:700;text-align:left;padding:7px 9px;font-size:11px;text-transform:uppercase;letter-spacing:.04em;white-space:nowrap}
