.st-danger{color:var(--st-dn);border-color:rgba(255,77,109,.35)}
.st-tfoot{padding:8px 10px;display:flex;justify-content:flex-end}
.st-empty{color:var(--st-mut);padding:22px 14px;margin:0;text-align:center}
.st-hbar{display:flex;gap:4px;flex-wrap:wrap;padding:10px;align-items:center}
