.st-hstats{display:flex;flex-wrap:wrap;gap:6px 22px;padding:0 12px 10px}.st-hstats small{display:block;color:var(--st-mut);font-size:10.5px;text-transform:uppercase}.st-hstats b{font-size:15px}
.st-up{color:var(--st-up)}.st-dn{color:var(--st-dn)}.st-warn{color:var(--st-warn)}.st-buy{color:var(--st-blue);font-weight:700}.st-sell{color:var(--st-dn);font-weight:700}

/* modal + toasts */
.st-modal{position:fixed;inset:0;z-index:80;background:rgba(2,4,10,.72);backdrop-filter:blur(3px);display:grid;place-items:center;padding:16px}
