  .st-mw .st-mwt{max-height:none}
  .st-tbr{margin-left:0}
  .st-src{flex-basis:100%}
  .st-acc{gap:6px 16px}.st-acc>div b{font-size:14px}
}
@media (prefers-reduced-motion:reduce){ .st-badge.st-live i,.st-dlg,.st-toast,.st-loading span{animation:none} }

.st-trail{font-size:10.5px;padding:1px 5px;border-radius:5px;background:rgba(61,123,255,.14);color:var(--electric);white-space:nowrap}   /* trailing stop marker */
