.fi-sec{padding:26px 0 8px;scroll-margin-top:calc(var(--nav-h) + 56px);border-radius:18px;transition:box-shadow .3s}
.fi-sec.fi-hl{box-shadow:0 0 0 2px rgba(139,92,246,.55);padding-left:12px;padding-right:12px}
.fi-h{display:flex;align-items:center;flex-wrap:wrap;gap:10px}.fi-h h2{margin:0;font-size:clamp(20px,2.4vw,26px)}
.fi-lead{color:var(--muted);margin:6px 0 14px;max-width:900px}
.fi-sim{display:grid;grid-template-columns:minmax(0,.95fr) minmax(0,1.05fr);gap:14px;align-items:start}
.fi-ins{display:grid;gap:10px;margin:0}
.fi-in label{display:flex;align-items:center;gap:6px;font-size:13.5px;font-weight:700}
.fi-i{width:18px;height:18px;border-radius:50%;border:1px solid var(--line-2);background:transparent;color:var(--muted);font:800 11px var(--body);cursor:pointer;display:grid;place-items:center;padding:0}
.fi-tip{margin:4px 0 0;font-size:12.5px;color:var(--muted);line-height:1.5}
.fi-ctl{display:flex;align-items:center;gap:10px;margin-top:4px}
.fi-ctl input[type=range]{flex:1;min-width:0;accent-color:var(--violet);height:28px}
.fi-box{display:flex;align-items:center;gap:2px;flex:none;height:36px;padding:0 8px;border-radius:10px;border:1px solid var(--line-2);background:rgba(255,255,255,.03)}
.fi-box i{font-style:normal;color:var(--muted);font-size:13px}
.fi-box input{width:96px;border:0;background:transparent;color:var(--text);font:700 14px var(--body);text-align:right;outline:none;-moz-appearance:textfield}
.fi-box input::-webkit-inner-spin-button{opacity:.5}
.fi-reset{justify-self:start;min-height:36px}
.fi-out{display:grid;gap:10px;min-width:0}
.fi-big{padding:18px;border-radius:18px;border:1px solid rgba(46,230,168,.35);background:linear-gradient(160deg,rgba(46,230,168,.10),rgba(255,255,255,.01))}
.fi-big small{display:block;font-size:12px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
.fi-big b{display:block;font-family:var(--display);font-size:clamp(26px,3.6vw,40px);color:var(--mint);margin:4px 0;font-variant-numeric:tabular-nums}
.fi-big b.neg{color:var(--rose)}.fi-big span{font-size:13px;color:var(--muted)}
.fi-big:has(b.neg){border-color:rgba(255,92,122,.4);background:linear-gradient(160deg,rgba(255,92,122,.10),rgba(255,255,255,.01))}
.fi-res{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.fi-res3{grid-template-columns:repeat(3,minmax(0,1fr))}
.fi-r{padding:12px;border-radius:14px;border:1px solid var(--line);background:rgba(255,255,255,.02);min-width:0}
.fi-r small{display:block;font-size:12px;color:var(--muted)}.fi-r b{display:block;font-size:17px;margin:2px 0;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.fi-r span{font-size:11.5px;color:var(--dim)}
.fi-r.neg b{color:var(--rose)}
.fi-formula,.fi-omit{margin:0;font-size:13px;color:var(--muted);line-height:1.55}.fi-omit{padding:10px 12px;border-radius:12px;border:1px dashed var(--line-2)}
.fi-learn{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:14px}
.fi-learn details{border-radius:14px;border:1px solid var(--line);background:rgba(139,92,246,.05);padding:10px 12px}
.fi-learn summary{cursor:pointer;font-weight:800;font-size:13.5px;color:var(--purple)}.fi-learn p{margin:8px 0 2px;font-size:13.5px;line-height:1.6;color:var(--muted)}
/* 3D money flow (the stage stays dark in both themes, like the Inside the Broker scene) */
.keep-colors.fi-stage{position:relative;aspect-ratio:16/8;border-radius:20px;overflow:hidden;border:1px solid rgba(110,140,230,.25);background:#03050b;touch-action:pan-y}
.fi-stage canvas{position:absolute;inset:0;width:100%;height:100%;display:block;cursor:grab}
.fi-cards{position:absolute;inset:0;pointer-events:none}
.keep-colors .fi-card{position:absolute;left:0;top:0;pointer-events:auto;cursor:pointer;padding:5px 9px;border-radius:10px;background:rgba(6,9,20,.82);border:1px solid rgba(143,210,255,.28);text-align:center;white-space:nowrap;transition:border-color .2s,box-shadow .2s;backdrop-filter:blur(4px);-webkit-backdrop-filter:blur(4px)}
.keep-colors .fi-card small{display:block;font-size:10px;color:#9fb3da}.keep-colors .fi-card b{display:block;font-size:13px;color:#EAF2FF;font-variant-numeric:tabular-nums}.keep-colors .fi-card span{font-size:9.5px;color:#7f93bd}
.keep-colors .fi-card.on{border-color:#8FD2FF;box-shadow:0 0 16px rgba(143,210,255,.35)}.keep-colors .fi-card.neg b{color:#FF8FA3}
.keep-colors .fi-pick{position:absolute;left:12px;right:12px;bottom:10px;margin:0;padding:8px 12px;border-radius:12px;background:rgba(3,5,11,.75);color:#cfd9f2;font-size:13px;pointer-events:none}
.fi-flow2{display:flex;align-items:center;flex-wrap:wrap;gap:6px;margin-top:10px}.fi-flow2>i{color:var(--muted);font-style:normal}
.fi-f2{padding:8px 10px;border-radius:12px;border:1px solid var(--line);min-width:0}.fi-f2 small{display:block;font-size:11px;color:var(--muted)}.fi-f2 b{font-size:14px;font-variant-numeric:tabular-nums}
.fi-f2.in b{color:var(--violet)}.fi-f2.end b{color:var(--mint)}.fi-f2.end.neg b{color:var(--rose)}
/* progression */
.fi-prog{display:grid;gap:12px}
.fi-sh{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;font-size:13.5px}.fi-sh span{color:var(--muted)}.fi-sh em{font-style:normal;font-weight:700}
.fi-sh em.fi-ok{color:var(--mint)}.fi-sh em.fi-bad{color:var(--rose)}
.fi-bar{display:flex;height:14px;border-radius:999px;overflow:hidden;background:rgba(255,255,255,.05);margin:6px 0 4px}
.fi-bar span{display:block;height:100%;transition:width .5s cubic-bezier(.2,.8,.2,1)}.fi-bar .in{background:var(--violet)}.fi-bar .fi-ok{background:var(--mint)}.fi-bar .fi-bad{background:rgba(255,92,122,.55)}
.fi-st p{margin:0;font-size:12.5px;color:var(--muted)}
.fi-final{margin:4px 0 0;font-size:15px}
/* influencer */
.fi-chain{display:flex;align-items:center;flex-wrap:wrap;gap:6px}
.fi-node{padding:10px 12px;border-radius:14px;border:1px solid rgba(139,92,246,.35);background:rgba(139,92,246,.07);min-width:0}.fi-node small{display:block;font-size:11px;color:var(--muted)}.fi-node b{font-size:14.5px;font-variant-numeric:tabular-nums}
.fi-dot{width:22px;height:2px;background:linear-gradient(90deg,var(--violet),var(--cyan));position:relative;flex:none}
.fi-dot::after{content:"";position:absolute;top:-3px;left:0;width:8px;height:8px;border-radius:50%;background:var(--cyan);animation:fiDot 1.6s linear infinite}
@keyframes fiDot{from{left:-4px}to{left:18px}}
.fi-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px;margin-top:14px}
.fi-tile{padding:12px;border-radius:14px;border:1px solid var(--line);background:rgba(255,255,255,.02)}.fi-tile b{font-size:14px}.fi-tile p{margin:6px 0 0;font-size:13px;color:var(--muted);line-height:1.5}
.fi-vs{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px}.fi-vs>div{padding:12px 14px;border-radius:14px;border:1px solid var(--line)}
.fi-vs>div:first-child{border-color:rgba(46,230,168,.35)}.fi-vs>div:last-child{border-color:rgba(255,92,122,.35)}
.fi-vs h3{margin:0 0 6px;font-size:15px}.fi-vs ul{margin:0;padding-left:18px;color:var(--muted);font-size:13.5px;line-height:1.6}
/* payouts */
.fi-pay{display:grid;grid-template-columns:.8fr 1.2fr;gap:12px}.fi-pay .jr-panel{margin:0}
.fi-vtag{display:inline-block;font-size:10.5px;font-weight:800;letter-spacing:.08em;padding:3px 8px;border-radius:999px;background:rgba(139,92,246,.15);color:var(--purple);margin-bottom:8px}
.fi-vtag.hypo{background:rgba(255,194,75,.13);color:var(--amber)}
.fi-ad{display:block;font-family:var(--display);font-size:clamp(18px,2.2vw,24px);line-height:1.25;margin:4px 0}
.fi-kv{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.fi-kv small{display:block;font-size:12px;color:var(--muted)}.fi-kv b{font-variant-numeric:tabular-nums}
.fi-verified{margin-top:12px}.fi-verified p{margin:0;color:var(--muted);font-size:13.5px;line-height:1.6}
/* rules */
.fi-rtabs{display:flex;gap:6px;overflow-x:auto;scrollbar-width:none;padding-bottom:6px}.fi-rtabs::-webkit-scrollbar{display:none}
.fi-rtabs button{flex:none;padding:8px 12px;border-radius:999px;border:1px solid var(--line-2);background:transparent;color:var(--muted);font:700 13px var(--body);cursor:pointer}
.fi-rtabs button[aria-selected="true"]{background:rgba(139,92,246,.22);color:var(--text);border-color:rgba(139,92,246,.55)}
.fi-rule{margin-top:6px}.fi-rule h3{margin:0 0 10px}
.fi-rq{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.fi-rq small,.fi-rex>small{font-size:11.5px;font-weight:800;letter-spacing:.06em;color:var(--purple)}.fi-rq p{margin:4px 0 0;font-size:13.5px;line-height:1.55;color:var(--muted)}
.fi-rex{margin-top:14px;padding:12px 14px;border-radius:14px;border:1px solid var(--line);background:rgba(255,255,255,.02)}
.fi-rc{display:block;font-size:13.5px;margin-top:8px}.fi-rc input{display:block;width:100%;accent-color:var(--violet);margin-top:4px}
.fi-rs{margin:10px 0 0;padding:10px 12px;border-radius:12px;font-size:14px;line-height:1.5}.fi-rs.fi-ok{background:rgba(46,230,168,.08);border:1px solid rgba(46,230,168,.35)}.fi-rs.fi-bad{background:rgba(255,92,122,.08);border:1px solid rgba(255,92,122,.35)}
/* timeline */
.fi-seg{display:inline-flex;gap:4px;padding:3px;border-radius:12px;border:1px solid var(--line-2);margin-bottom:12px;flex-wrap:wrap}
.fi-seg button{min-height:34px;padding:0 12px;border:0;border-radius:9px;background:transparent;color:var(--muted);font:700 13px var(--body);cursor:pointer}.fi-seg button[aria-pressed="true"]{background:rgba(139,92,246,.25);color:var(--text)}
.fi-chart svg{width:100%;height:auto;display:block;overflow:visible}.fi-chart text{font:600 10px var(--body);fill:var(--muted)}
.fi-ax{stroke:var(--line-2)}.fi-cum{fill:none;stroke:var(--text);stroke-width:2;stroke-dasharray:5 4}
.fi-g{transform-box:fill-box;transform-origin:bottom;animation:fiGrow .5s cubic-bezier(.2,.8,.2,1) both}
@keyframes fiGrow{from{transform:scaleY(0)}to{transform:scaleY(1)}}
.fi-legend{display:flex;flex-wrap:wrap;gap:6px 14px;font-size:12px;color:var(--muted);margin-top:6px}.fi-legend span{display:inline-flex;align-items:center;gap:5px}.fi-legend i{width:10px;height:10px;border-radius:3px;display:inline-block}
.fi-legend i.ln{height:0;border-top:2px dashed var(--text);border-radius:0}
.fi-tablewrap{overflow-x:auto;margin-top:12px;border-radius:14px;border:1px solid var(--line)}
.fi-table{width:100%;border-collapse:collapse;font-size:13px;font-variant-numeric:tabular-nums;white-space:nowrap}.fi-table th,.fi-table td{padding:8px 10px;text-align:right;border-bottom:1px solid var(--line)}
.fi-table th:first-child,.fi-table td:first-child{text-align:left}.fi-table th{color:var(--muted);font-weight:700}.fi-table td.neg{color:var(--rose)}
/* marketing vs reality */
.fi-mkt{display:grid;gap:8px}.fi-claim{display:grid;grid-template-columns:.8fr 1.2fr;border-radius:14px;border:1px solid var(--line);overflow:hidden}
.fi-claim>div{padding:12px 14px}.fi-claim>div:first-child{background:rgba(139,92,246,.07)}.fi-claim small{display:block;font-size:10.5px;font-weight:800;letter-spacing:.08em;color:var(--muted)}
.fi-claim b{font-size:15.5px}.fi-claim p{margin:4px 0 0;font-size:13.5px;line-height:1.55;color:var(--muted)}
/* $100 */
.fi-stack{display:flex;height:42px;border-radius:12px;overflow:hidden;background:rgba(255,255,255,.04)}.fi-stack span{display:block;height:100%;transition:width .45s cubic-bezier(.2,.8,.2,1)}
#fiLegend{display:grid;gap:6px}#fiLegend div{display:grid;grid-template-columns:12px 1fr auto 64px;align-items:center;gap:8px;font-size:13.5px}#fiLegend b{font-variant-numeric:tabular-nums}#fiLegend small{text-align:right;color:var(--muted)}
.fi-disc{margin:20px 0 10px}.fi-disc p{margin:6px 0 0;color:var(--muted);font-size:13.5px;line-height:1.65}
/* guided walkthrough */
.fi-tour{position:fixed;left:50%;bottom:calc(16px + env(safe-area-inset-bottom,0px));transform:translateX(-50%);z-index:60;width:min(560px,calc(100% - 24px))}
.fi-tb{padding:14px 16px;border-radius:18px;border:1px solid rgba(139,92,246,.5);background:var(--panel);box-shadow:0 24px 60px -20px rgba(0,0,0,.7)}
.fi-tb small{font-size:11px;font-weight:800;letter-spacing:.1em;color:var(--purple)}.fi-tb b{display:block;font-size:16px;margin:2px 0 4px}.fi-tb p{margin:0;font-size:13.5px;color:var(--muted);line-height:1.55}
.fi-tdots{display:flex;gap:4px;margin:10px 0}.fi-tdots i{width:6px;height:6px;border-radius:50%;background:var(--line-2)}.fi-tdots i.on{background:var(--violet);width:16px;border-radius:3px}
.fi-tbtn{display:flex;gap:8px;justify-content:flex-end}.fi-tbtn .btn{min-height:36px;padding:0 14px}
@media (max-width:1100px){ .fi-grid{grid-template-columns:repeat(3,minmax(0,1fr))} }
@media (max-width:900px){ .fi-sim,.fi-pay{grid-template-columns:1fr} .fi-learn,.fi-rq{grid-template-columns:1fr} .keep-colors.fi-stage{aspect-ratio:4/5} .fi-tour{bottom:calc(var(--bnav-h,66px) + 10px + env(safe-area-inset-bottom,0px))} }
@media (max-width:560px){ .fi-res,.fi-res3{grid-template-columns:repeat(2,minmax(0,1fr))} .fi-grid,.fi-vs{grid-template-columns:1fr} .fi-claim{grid-template-columns:1fr} .fi-kv{grid-template-columns:1fr 1fr}
  .fi-box input{width:84px} .keep-colors .fi-card{padding:3px 6px} .keep-colors .fi-card small,.keep-colors .fi-card span{display:none} .keep-colors .fi-card b{font-size:11px} }
@media (prefers-reduced-motion:reduce){ .fi-g,.fi-dot::after{animation:none} .fi-bar span,.fi-stack span{transition:none} }
@media (pointer:coarse){ .fi-ctl input[type=range]{height:38px} .fi-box{height:40px} .fi-i{width:24px;height:24px} }   /* comfortable touch targets */
/* home page section (fiHomeSection) */
.fih{margin:34px 0 10px}.fih .s-kicker{margin:0}
.fih-top{display:flex;justify-content:space-between;align-items:flex-end;gap:16px;flex-wrap:wrap;margin-bottom:14px}.fih-top .h{margin:2px 0}.fih-top .sub{margin:6px 0 0;max-width:760px}
.fih .fi-prog{gap:8px}
.fih-topics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-top:14px}
.fih-topics .hb-card{flex-direction:row;align-items:center;gap:10px}.fih-topics .hb-card b{font-size:13.5px}
@media (max-width:900px){ .fih-topics{grid-template-columns:repeat(2,minmax(0,1fr))} }
@media (max-width:520px){ .fih-topics{grid-template-columns:1fr} }
/* tabs (owner, 2026-11-18): Simulator · Money Flow · Payouts · Revenue */
.fi-tabs{position:sticky;top:calc(var(--nav-h) + env(safe-area-inset-top,0px));z-index:8;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px;padding:8px 0;margin:6px 0 4px;background:var(--obsidian)}
.fi-tabs button{padding:10px 8px;border-radius:12px;border:1px solid var(--line-2);background:var(--panel);color:var(--muted);font:inherit;font-size:14px;font-weight:700;cursor:pointer;white-space:nowrap}
.fi-tabs button:hover{color:var(--text)}
.fi-tabs button[aria-selected="true"]{color:var(--text);border-color:var(--text);box-shadow:inset 0 -2px 0 var(--text)}
.fi-sec[hidden]{display:none!important}
@media (max-width:960px){ .fi-tabs{position:static} }   /* phones: only the bottom bar stays fixed */
@media (max-width:420px){ .fi-tabs button{font-size:12.5px;padding:9px 4px} }
/* @@FUNDINS-CSS-END */
/* @@UIKIT-CSS-START */
/* UI kit: toasts, skeletons, data messages (frontend/uikit/uikit.js) */
.ui-toasts{position:fixed;left:50%;bottom:calc(env(safe-area-inset-bottom,0px) + 84px);transform:translateX(-50%);z-index:140;display:flex;flex-direction:column;gap:8px;align-items:center;pointer-events:none;width:min(420px,calc(100vw - 32px))}
.ui-toast{pointer-events:auto;padding:11px 16px;border-radius:12px;background:var(--panel-2);border:1px solid var(--line-2);color:var(--text);font-size:14px;box-shadow:0 10px 30px -12px rgba(0,0,0,.6);animation:uiIn .2s ease;transition:opacity .3s}
.ui-toast.ok{border-left:3px solid var(--mint)}.ui-toast.warn{border-left:3px solid var(--amber)}.ui-toast.err{border-left:3px solid var(--rose)}
.ui-toast.out{opacity:0}
@keyframes uiIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
.ui-skel{display:flex;flex-direction:column;gap:10px;padding:4px 0}
.ui-skel i{display:block;height:12px;border-radius:6px;background:linear-gradient(90deg,var(--panel-2) 0%,rgba(148,170,220,.12) 50%,var(--panel-2) 100%);background-size:200% 100%;animation:uiShim 1.4s linear infinite}
@keyframes uiShim{from{background-position:200% 0}to{background-position:-200% 0}}
.ui-msg{margin:0;padding:10px 0;color:var(--muted);font-size:13.5px;line-height:1.5}
.ui-msg a{color:var(--electric)}
@media (min-width:961px){ .ui-toasts{bottom:24px} }
