.ws{padding-bottom:40px}
.ws-hd{padding-bottom:6px}
.ws-bar{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px 16px;padding:10px 0 12px;border-bottom:1px solid var(--line);margin-bottom:14px}
