.ws-tab{flex-shrink:0;height:36px;padding:0 14px;border-radius:10px;border:1px solid transparent;background:none;color:var(--muted);font-weight:600;font-size:13.5px;cursor:pointer}
.ws-tab:hover{color:var(--text)}
