.ws-editbar p{margin:0;font-size:12.5px;flex-basis:100%}
.ws-del{color:var(--rose)}
#wsRoot{position:relative}
.ws-pop{position:absolute;z-index:30;width:min(320px,calc(100vw - 32px));max-height:60vh;overflow:auto;padding:6px;border-radius:14px;border:1px solid var(--line-2);background:var(--charcoal);box-shadow:0 20px 50px -20px rgba(0,0,0,.7)}
.ws-pop button{display:flex;flex-direction:column;align-items:flex-start;gap:2px;width:100%;padding:9px 10px;border:0;border-radius:9px;background:none;color:var(--text);text-align:left;cursor:pointer;font-size:14px}
