.ws-pop small{color:var(--muted);font-size:12px}
.ws-grid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));grid-auto-rows:56px;grid-auto-flow:row dense;gap:12px}
.wsw{grid-column:span var(--w);grid-row:span var(--h);position:relative;display:flex;flex-direction:column;min-width:0;border:1px solid var(--line);border-radius:14px;background:var(--panel);overflow:hidden}
.wsw-h{display:flex;align-items:center;gap:8px;padding:9px 12px;border-bottom:1px solid var(--line);min-height:42px}
.wsw-h h3{margin:0;font-size:13.5px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.wsw-sym{font-size:11px;font-weight:700;letter-spacing:.04em;color:var(--electric);background:rgba(61,123,255,.12);padding:2px 7px;border-radius:6px}
.wsw-tools{margin-left:auto;display:flex;gap:2px;flex-shrink:0}
.wsw-tools button,.wsw-grip{height:28px;min-width:28px;padding:0 6px;border-radius:7px;border:1px solid var(--line);background:var(--panel-2);color:var(--muted);font-size:12px;cursor:pointer}
.wsw-tools button:hover,.wsw-grip:hover{color:var(--text);border-color:var(--line-2)}
.wsw-x{color:var(--rose)!important}
.wsw-grip{cursor:grab;touch-action:none;font-size:15px;line-height:1}
.wsw-b{flex:1;min-height:0;overflow:auto;padding:10px 12px;display:flex;flex-direction:column;gap:8px;font-size:13.5px}
.editing .wsw{border-style:dashed;border-color:var(--line-2)}
.wsw.dragging{opacity:.55;outline:2px solid var(--electric)}
.wsw.resizing{outline:2px solid var(--electric)}
.wsw-rs{position:absolute;right:0;bottom:0;width:22px;height:22px;cursor:nwse-resize;touch-action:none;background:linear-gradient(135deg,transparent 50%,var(--electric) 50%);opacity:.7;border-bottom-right-radius:14px}
.ws-empty{grid-column:1/-1;grid-row:span 4;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;border:1px dashed var(--line-2);border-radius:14px;text-align:center;padding:20px}
.ws-empty h2{margin:0;font-size:18px}
.ws-note{font-size:12px;margin:16px 0 0}
.ws-row{display:flex;align-items:center;justify-content:space-between;gap:8px}
.ws-big{font-size:20px;font-weight:800;letter-spacing:-.01em}
.ws-mini{height:28px;border-radius:7px;border:1px solid var(--line-2);background:var(--panel-2);color:var(--text);font-size:12px;padding:0 6px}
.ws-cv{flex:1;min-height:120px;width:100%;display:block;touch-action:pan-y}
.ws-foot{display:flex;flex-wrap:wrap;align-items:center;gap:6px 12px;margin-top:auto;font-size:11.5px;color:var(--dim)}
.ws-foot a,.ws-ai a,.wsw-b>a{margin-left:auto;color:var(--electric);text-decoration:none;font-weight:600;font-size:12.5px}
.ws-src b{font-size:10px;letter-spacing:.06em;padding:1px 6px;border-radius:5px;margin-right:4px}
.ws-src b.live{background:rgba(34,201,142,.14);color:var(--mint)}
.ws-src b.delayed{background:rgba(255,194,75,.14);color:var(--amber)}
.ws-tag{margin:0;font-size:11.5px;color:var(--dim);line-height:1.45}
.ws-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column}
.ws-list li{display:grid;grid-template-columns:1fr auto;gap:0 10px;padding:7px 0;border-bottom:1px solid var(--line)}
.ws-list li:last-child{border-bottom:0}
.ws-list li span{color:var(--muted);display:flex;align-items:center;gap:6px}
.ws-list li b{font-weight:700;text-align:right}
.ws-list li small{grid-column:1/-1;color:var(--dim);font-size:11.5px}
.ws-list .dot{width:8px;height:8px;border-radius:50%;display:inline-block}
.ws .up{color:var(--mint)}.ws .dn{color:var(--rose)}
.ws-bias{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.ws-bias div{padding:8px 10px;border-radius:10px;background:var(--panel-2)}
.ws-bias small{display:block;font-size:11px;color:var(--dim)}
.ws-bias b{font-size:14px}
.ws-mtf{display:flex;flex-wrap:wrap;gap:4px}
.ws-mtf span{font-size:11px;padding:3px 7px;border-radius:6px;background:var(--panel-2);color:var(--muted)}
.ws-mtf span b{font-weight:700}
.ws-mtf span.up b{color:var(--mint)}.ws-mtf span.dn b{color:var(--rose)}
.ws-caut{display:flex;flex-direction:column;gap:6px;padding:10px;border-radius:10px;border:1px solid var(--line);background:var(--panel-2)}
.ws-caut>b{font-size:12px;letter-spacing:.04em}
.ws-caut ul{margin:0;padding-left:18px;display:flex;flex-direction:column;gap:4px;font-size:12.5px;color:var(--text)}
.ws-caut li.high::marker{color:var(--rose)}.ws-caut li.medium::marker{color:var(--amber)}
.ws-ai{display:flex;align-items:center;gap:10px}
.ws-ai .btn{min-height:34px;padding:0 12px;font-size:13px}
.ws-aitext{font-size:13px;line-height:1.6;color:var(--text);padding:10px;border-radius:10px;background:var(--panel-2)}
.ws-wl{display:flex;flex-direction:column}
.ws-wlr{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:8px 6px;border:0;border-bottom:1px solid var(--line);background:none;color:var(--text);text-align:left;cursor:pointer;border-radius:8px}
.ws-wlr:hover{background:var(--panel-2)}
.ws-wlr[aria-current="true"]{background:rgba(61,123,255,.1);box-shadow:inset 3px 0 0 var(--electric)}
.ws-wlr span{display:flex;flex-direction:column}
.ws-wlr span:last-child{align-items:flex-end;font-weight:700}
.ws-wlr small{font-size:11px;color:var(--dim);font-weight:500}
.ws-wlr small.up{color:var(--mint)}.ws-wlr small.dn{color:var(--rose)}
.ws-pick summary{cursor:pointer;font-size:12.5px;color:var(--electric)}
.ws-pick div{display:flex;flex-wrap:wrap;gap:6px 12px;padding-top:6px;font-size:12.5px}
.ws-form{display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:8px}
.ws-form label{display:flex;flex-direction:column;gap:4px;font-size:11.5px;color:var(--dim)}
.ws-form input{height:36px;border-radius:9px;border:1px solid var(--line-2);background:var(--panel-2);color:var(--text);padding:0 10px;font-size:14px;min-width:0}
.ws-calc-r{padding:10px 12px;border-radius:10px;background:rgba(61,123,255,.1);border:1px solid rgba(61,123,255,.25)}
.ws-calc-r small{display:block;font-size:11.5px;color:var(--muted)}
.ws-calc-r b{font-size:22px;font-weight:800}
.ws-chk{font-size:12px;color:var(--muted);display:flex;align-items:center;gap:5px;white-space:nowrap}
.ws-cal{list-style:none;margin:0;padding:0}
.ws-cal li{display:grid;grid-template-columns:86px 1fr;gap:10px;padding:8px 0;border-bottom:1px solid var(--line)}
.ws-cal li.past{opacity:.6}
.ws-cal li>span:first-child{font-weight:700;font-size:12.5px;display:flex;flex-direction:column}
.ws-cal small{display:block;color:var(--dim);font-size:11.5px;font-weight:500}
.ws-cal .imp{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:6px;background:var(--dim)}
.ws-cal .imp.high{background:var(--rose)}.ws-cal .imp.medium{background:var(--amber)}
.ws-stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(90px,1fr));gap:6px}
.ws-stats div{padding:8px;border-radius:9px;background:var(--panel-2)}
.ws-stats small{display:block;font-size:11px;color:var(--dim)}
.ws-stats b{font-size:15px}
.ws-warn{margin:0;padding:8px 10px;border-radius:9px;background:rgba(240,80,110,.1);color:var(--rose);font-size:12.5px;font-weight:600}
.ws-notes{flex:1;min-height:80px;width:100%;resize:none;border:1px solid var(--line);border-radius:10px;background:var(--panel-2);color:var(--text);padding:10px;font:inherit;font-size:13.5px;line-height:1.55}
@media (max-width:1100px){ .wsw{grid-column:span max(6,var(--w))} }
@media (max-width:760px){
  .ws-grid{grid-template-columns:1fr;grid-auto-rows:auto}
  .wsw{grid-column:1/-1;grid-row:auto;min-height:calc(var(--h) * 56px)}
  .ws-ctl{width:100%;display:grid;grid-template-columns:1fr 1fr;gap:8px}
  .ws-sel{flex-direction:column;align-items:stretch;gap:3px}.ws-sel select{width:100%}
  .ws-edit{grid-column:1/-1}#wsSaved{grid-column:1/-1}
  .wsw-tools button[data-wa="narrow"],.wsw-tools button[data-wa="wide"]{display:none}
  .wsw-rs{display:none}
}
