.sa-tutor{padding:14px 16px;border:1px solid var(--line);border-radius:14px;background:var(--panel)}
.sa-tutor h3{margin:0 0 4px;font-size:15px}.sa-tutor>p{margin:0 0 10px;font-size:12.5px}
