/* @@MCENTER-CSS-START */
/* Market Intelligence Center (frontend/mcenter/mcenter.js) */
.mc{padding-bottom:40px}
.mc-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
.mc-card{padding:16px;border:1px solid var(--line);border-radius:16px;background:var(--panel);min-width:0;display:flex;flex-direction:column;gap:10px}
.mc-wide{grid-column:span 2}
.mc-card h2{margin:0;font-size:16px;font-weight:800}
.mc-h{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap}
.mc-seg{display:flex;gap:2px;padding:3px;border-radius:10px;background:var(--panel-2)}
.mc-seg button{border:0;background:none;color:var(--muted);font:inherit;font-size:12.5px;font-weight:700;padding:5px 10px;border-radius:8px;cursor:pointer}
.mc-seg button[aria-pressed="true"]{background:var(--panel);color:var(--text)}
.mc-bars{display:flex;flex-direction:column;gap:7px}
.mc-bar{display:grid;grid-template-columns:44px 1fr 46px 60px;align-items:center;gap:10px;font-size:13px}
.mc-track{position:relative;height:10px;border-radius:5px;background:var(--panel-2)}
.mc-track::after{content:"";position:absolute;left:50%;top:-3px;bottom:-3px;width:1px;background:var(--line-2)}
.mc-track i{position:absolute;top:0;bottom:0;border-radius:5px}
.mc-track i.up{background:var(--mint)}.mc-track i.dn{background:var(--rose)}
.mc-bar em{font-style:normal;font-weight:800;text-align:right}.mc-bar small{color:var(--dim);font-size:11.5px}
.mc .up{color:var(--mint)}.mc .dn{color:var(--rose)}
.mc-src{margin:0;font-size:11.5px;color:var(--dim);line-height:1.5}.mc-src a{color:var(--electric)}
.mc-pill{display:inline-block;font-size:10.5px;font-weight:800;letter-spacing:.05em;padding:2px 7px;border-radius:6px;background:var(--panel-2);color:var(--muted);margin-right:4px}
.mc-pill.ok{background:rgba(34,201,142,.14);color:var(--mint)}.mc-pill.warn{background:rgba(255,194,75,.14);color:var(--amber)}.mc-pill.bad{background:rgba(240,80,110,.14);color:var(--rose)}
.mc-tbl{width:100%;border-collapse:collapse;font-size:13px}
.mc-tbl th,.mc-tbl td{padding:7px 8px;border-bottom:1px solid var(--line);text-align:left;white-space:nowrap}
.mc-tbl th{font-size:11.5px;color:var(--dim);font-weight:600}
.mc-lean{margin:0;font-size:20px;font-weight:800}
.mc-split{display:flex;height:12px;border-radius:6px;overflow:hidden;background:var(--panel-2)}
.mc-split i.up{background:var(--mint)}.mc-split i.neu{background:var(--dim)}.mc-split i.dn{background:var(--rose)}
.mc-legend{margin:0;font-size:12.5px;color:var(--muted)}
.mc-chips{display:flex;flex-wrap:wrap;gap:5px}
.mc-chip{font-size:11.5px;padding:3px 8px;border-radius:7px;background:var(--panel-2);color:var(--muted)}
.mc-chip.up{color:var(--mint)}.mc-chip.dn{color:var(--rose)}
.mc-list{list-style:none;margin:0;padding:0}
.mc-list li{display:grid;grid-template-columns:1fr auto;gap:2px 10px;padding:7px 0;border-bottom:1px solid var(--line);font-size:13px}
.mc-list li span{display:flex;align-items:center;gap:6px;min-width:0}
.mc-list li small{grid-column:1/-1;color:var(--dim);font-size:11.5px}
.mc-dot{width:8px;height:8px;border-radius:50%;display:inline-block}
.mc-prefs{display:flex;flex-direction:column;gap:8px;font-size:13px}
.mc-prefs label{display:flex;flex-direction:column;gap:4px;color:var(--muted)}
.mc-prefs select{height:36px;border-radius:9px;border:1px solid var(--line-2);background:var(--panel-2);color:var(--text);padding:0 8px}
.mc-prefs .mc-chk{flex-direction:row;align-items:center;gap:8px;color:var(--text)}
.mc-ccy{display:flex;flex-wrap:wrap;gap:6px 12px}.mc-ccy label{flex-direction:row;align-items:center;gap:5px;color:var(--text)}
.mc-prefs .btn{align-self:flex-start;min-height:38px}
.mc-fine{font-size:12px;color:var(--dim);margin-top:16px}
@media (max-width:1100px){ .mc-grid{grid-template-columns:repeat(2,minmax(0,1fr))} }
@media (max-width:760px){ .mc-grid{grid-template-columns:1fr} .mc-wide{grid-column:auto} .mc-tbl{font-size:12px} }
