.lab-chk{flex-direction:row!important;align-items:center;gap:8px!important;color:var(--text)!important;min-height:38px}
.lab-run{width:100%}
.lab-fine{margin:0;font-size:11.5px;color:var(--dim);line-height:1.5}
.lab-out{display:flex;flex-direction:column;gap:14px;min-width:0}
.lab-empty{padding:40px 20px;text-align:center;border:1px dashed var(--line-2);border-radius:16px}
