.lab-ds{margin:0;font-size:13px;color:var(--muted)}
.lab-kpis{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:8px}
.lab-kpis div{padding:10px 12px;border-radius:12px;border:1px solid var(--line);background:var(--panel)}
.lab-kpis small{display:block;font-size:11.5px;color:var(--dim)}
.lab-kpis b{font-size:18px;font-weight:800;font-variant-numeric:tabular-nums}
