.lab-card h3 small{font-size:12px;color:var(--dim);font-weight:500}
#labEq{width:100%;height:220px;display:block}
.lab-tbl{width:100%;border-collapse:collapse;font-size:13px}
.lab-tbl th,.lab-tbl td{padding:8px 10px;border-bottom:1px solid var(--line);text-align:right;white-space:nowrap}
.lab-tbl th:first-child,.lab-tbl td:first-child{text-align:left}
