.lab-tbl thead th small{display:block;font-weight:500;white-space:normal;max-width:220px;margin:2px 0 4px auto}
.lab-tbl tbody th{color:var(--muted);font-weight:600}
.lab-acts{display:flex;flex-wrap:wrap;gap:10px}
.lab-acts .btn{min-height:42px;font-size:14px}
@media (max-width:960px){ .lab-grid{grid-template-columns:1fr} .lab-form{position:static;max-height:none} }
