/* Global search / command palette (frontend/palette/palette.js) */
.pal-btn{display:inline-flex;align-items:center;gap:8px;height:40px;padding:0 10px 0 12px;border-radius:12px;border:1px solid var(--line-2);background:var(--panel);color:var(--muted);font:inherit;font-size:13px;cursor:pointer;flex-shrink:0}
